(window.WCD=window.WCD||[]).push(["maroc",[["Q170525",1,"ville","Agadir","R","Agadir, aussi appelée Agadir Irir est une ville du centre-ouest marocain, située sur la côte atlantique, à 508 km au sud de Casablanca, et à 235 km à l'ouest de Marrakech. Surnommée « la capitale du Souss », Agadir est le chef-lieu de la région administrative Souss-Massa et de la préfecture d'Agadir Ida-Outanane.",116,"fr:Agadir","c:1/16/%D9%85%D8%A7%D8%B1%D9%8A%D9%86%D8%A7_%D8%A3%D9%83%D8%A7%D8%AF%D9%8A%D8%B1.jpg"],["Q310350",2,"ville","Al Hoceïma","C","Al Hoceïma est une ville située sur la côte nord du Maroc, à 291 km de Tanger à l'ouest et à 205 km de Saïdia. La ville est la capitale culturelle du Rif.","Al Hoceïma est une ville située sur la côte nord du Maroc, à 291 km de Tanger à l'ouest et à 205 km de Saïdia.","fr:Al_Hoceïma","c:2/2f/AlhWik.jpg"],["Q730328",3,"ville","Assilah","C","Assilah, Arzila ou Arcila est une ville au nord-ouest du Maroc d'environ 30 000 habitants, à une quarantaine de kilomètres de Tanger, dans la préfecture de Tanger-Assilah, région de Tanger-Tétouan-Al Hoceïma.",111,"fr:Assilah","c:e/e4/Assilah_06.jpg"],["Q794128",4,"ville","Azrou","C","Azrou est une ville marocaine située à 18 km au sud-ouest d'Ifrane. Azrou est notamment connu pour ses paysages en période d’hiver, au même titre qu'Ifrane, mais surtout grâce à ses singes macaques de Barbarie, une espèce en voie de disparition, qui vit dans la forêt d'Azrou.","Azrou est une ville marocaine située à 18 km au sud-ouest d'Ifrane.","fr:Azrou_(Maroc)","c:6/68/Azrou%2Ccenterfromhill.jpg"],["Q820813",5,"ville","Berkane","C","Berkane est une ville du Maroc, située dans la région de l'Oriental, dans le nord-est du pays. Elle est le chef-lieu de la province de Berkane.","Berkane est une ville du Maroc, située dans la région de l'Oriental, dans le nord-est du pays.","fr:Berkane","c:a/a9/Berkane_letchina.JPG"],["Q817279",6,"ville","Béni Mellal","PC","Béni Mellal est une ville marocaine située au centre du Maroc au pied du Moyen-Atlas, à la limite de la plaine de la Tadla. Avec une population de plus de 200 000 habitants, elle est la principale ville et le chef-lieu de la région de Beni Mellal-Khenifra.",116,"fr:Béni_Mellal","c:2/26/La_cath%C3%A9drale_mountain%2C_Beni_Mellal.jpg"],["Q676778",8,"ville","Chefchaouen","R","Chefchaouen ou Chaouen est une ville du nord-ouest du Maroc, bâtie à 600 m d'altitude au pied des monts Kelaa et Meggou, entre Tétouan et Ouazzane, sur la chaîne du Rif. Elle est le chef-lieu de la province homonyme. Sa population intra-muros est de 42 786 habitants.",112,"fr:Chefchaouen","c:e/e3/CHEFCHAOUEN_KASBAH.jpg"],["Q345204",9,"ville","Dakhla","PC","Dakhla est une ville située au Sahara occidental, territoire non autonome selon le droit international, occupée par le Maroc depuis son évacuation par la Mauritanie en 1979. Dans le cadre de l'organisation territoriale du Maroc, cette ville est une commune urbaine, chef-lieu de la province d'Oued Ed-Dahab, au sein de la région Dakhla-Oued Ed-Dahab.",118,"fr:Dakhla","c:7/77/Dakhla%2C_Western_Sahara_%2811%29.jpg"],["Q219583",10,"ville","El Jadida","PC","El-Jadida ou al-Jadida – avec anciens noms al-Brija, Mazagan et al-Mahdouma – est une ville côtière du Maroc, à 96 km au sud-ouest de Casablanca, chef-lieu de la province d'El Jadida. La cité fortifiée, édifiée par les Portugais au début du XVIe siècle et nommée Mazagan, fut prise par les Marocains en 1769.",117,"fr:El_Jadida","c:7/76/Forteresse_Jadida_01.JPG"],["Q648987",11,"ville","Erfoud","C","Erfoud (en berbère: ⴰⵔⴼⵓⴷ, en arabe: أرفود) est une ville du Maroc. Elle est située dans la région de Drâa-Tafilalet.","Erfoud (en berbère: ⴰⵔⴼⵓⴷ, en arabe: أرفود) est une ville du Maroc.","fr:Erfoud","c:8/89/Erfoud_City_Center_Morocco.jpg"],["Q1980885",12,"ville","Errachidia","C","Errachidia (en arabe: الرشيدية, anciennement Ksar Es-Souk ou \"Imtaghren\" en tamazight, est une ville du Maroc, chef-lieu de la province d'Errachidia, dans la région de Drâa Tafilalet.",110,"fr:Errachidia","c:0/04/Errachidia_north_view.jpg"],["Q216939",13,"ville","Essaouira","R","Essaouira est une ville portuaire du Souss et une commune du Maroc, chef-lieu de la province d'Essaouira, dans la région de Marrakech-Safi. Elle est située au bord de l'océan Atlantique et compte 82 094 habitants en 2024.",113,"fr:Essaouira","c:a/a1/Essaouira_Atlantic.jpg"],["Q80985",14,"ville","Fès","R","Fès ou Fez est une ville du Maroc septentrional, située à 180 km à l'est de Rabat, entre le massif du Rif et le Moyen Atlas. Faisant partie des villes impériales du Maroc, elle a été à plusieurs époques la capitale du pays et est considérée de nos jours comme sa capitale spirituelle.",117,"fr:Fès","c:4/44/University_karaouiyine_fes.jpg"],["Q842806",15,"ville","Guelmim","C","Guelmim (Agoulmim en berbère, en arabe:ݣلميم; anciennement écrite en français Goulimine), est une ville du centre-ouest du Maroc, chef-lieu de la province de Guelmim et capitale de la région Guelmim-Oued Noun. Selon une hypothèse, Guelmim viendrait du terme berbère « Agoulmim » qui veut dire « lac », « étang ».",119,"fr:Guelmim","c:8/83/Guelmim_morocco_Algasba.jpg"],["Q1001887",16,"ville","Ifrane","PC","Ifrane est une ville et commune urbaine du Maroc située dans le Moyen-Atlas, à 1 650 mètres d'altitude. Elle est le chef-lieu de la province d'Ifrane, dans la région administrative de Fès-Meknès, et compte une population de 13 558 habitants.","Ifrane est une ville et commune urbaine du Maroc située dans le Moyen-Atlas, à 1 650 mètres d'altitude.","fr:Ifrane","c:7/71/Neige_ifrane.jpg"],["Q6004235",17,"ville","Imlil","C","Ne doit pas être confondu avec Imlil dans la région Béni Mellal-Khénifra.",null,"fr:Imlil","c:e/ee/Imlil_.jpg"],["Q595974",18,"ville","Khouribga","C","Khouribga chef-lieu de la province du même nom, est une ville du Maroc de 191 807 habitants, située à environ 120 km de Casablanca, 154 km de la capitale, Rabat, plus de 200 km de Marrakech, 289 km de Fès, 444 km de Tanger. Cette cité minière est considérée comme la plus importante zone de production de phosphates du monde. Le Groupe OCP, la première entreprise publique du Maroc, exploite la zone minière du bassin d'Ouled Abdoun et gère en partie les infrastructures sportives et sociales de la ville.",119,"fr:Khouribga","c:1/1b/Ancien_terril_phosphate_OCP_Khouribga.jpg"],["Q1046653",19,"ville","Khémisset","C","Khémisset est une ville du Maroc. Elle est le chef-lieu de la province du même nom, la province de Khémisset. Elle est située dans la région de Rabat-Salé-Kénitra. En 2012, Khémisset compte 185 124 habitants.","Khémisset est une ville du Maroc.","fr:Khémisset","c:4/4f/Khemisset_mosque.jpg"],["Q478207",20,"ville","Kénitra","PC","Kénitra est une ville du Maroc. Pendant le protectorat français, la ville porte le nom de Port-Lyautey.","Kénitra est une ville du Maroc.","fr:Kénitra","c:a/a9/Kenitra_main_pic.jpg"],["Q606775",21,"ville","Larache","PC","Larache (arabe: العرائش, berbère: ⴰⵄⵔⵉⵛ) est une ville marocaine, chef-lieu de la province de Larache, dans la région de Tanger-Tétouan-Al Hoceïma, située à environ 86 kilomètres au sud de Tanger.",117,"fr:Larache","c:9/9d/Larache_de_nuit_%2814161711729%29.jpg"],["Q47837",22,"ville","Laâyoune","R","Laâyoune est la ville la plus importante du Sahara occidental. Elle est située au bord de l'Atlantique, à 500 km au sud d'Agadir et à 500 km à l'ouest de Tindouf, sur la route menant à Dakhla. Elle est traversée par l'oued Sakia El Hamra, sur lequel se trouve le barrage Sakia El Hamra.","Laâyoune est la ville la plus importante du Sahara occidental.","fr:Laâyoune","c:7/7e/Monumental_Arch%2C_Laayoune.jpg"],["Q2626632",25,"ville","Martil","C","Martil est une ville marocaine rifaine située au nord-est de Tétouan, au bord de la mer Méditerranée, dans la région de Tanger-Tétouan-Al Hoceïma. Alors qu'elle faisait partie de la province de Tétouan, elle a été rattachée à la préfecture de M'diq-Fnideq depuis 2010.",119,"fr:Martil","c:1/1f/Martil_2.jpg"],["Q178663",26,"ville","Meknès","PC","Meknès est une ville et commune du Maroc, chef-lieu de la préfecture de Meknès au sein de la région de Fès-Meknès. Elle est située sur le plateau de Saïss entre les massifs du Rif et du Moyen Atlas, et son territoire est traversé par la vallée du Oued Boufakrane.","Meknès est une ville et commune du Maroc, chef-lieu de la préfecture de Meknès au sein de la région de Fès-Meknès.","fr:Meknès","c:e/e6/Walili_volubilis.jpg"],["Q1922278",27,"ville","Merzouga","C","Merzouga est un petit village Chleuh Ait Atta situé dans le sud-est du Maroc, à 35 kilomètres de Moulay Ali Cherif, à 50 kilomètres de Erfoud, à 562 km de Marrakech, à 667 km de Casablanca, et à 669 km d'Agadir.",117,"fr:Merzouga","c:9/92/Adobe_Arches_in_Merzouga.jpg"],["Q2501809",28,"ville","Midelt","C","Midelt est une ville du Maroc, à la jonction des chaînes du Moyen Atlas et du Haut Atlas oriental, et une commune urbaine de la province de Midelt. La population de la commune, de 44 781 habitants en 2004, serait de 55 400 habitants en 2012.",113,"fr:Midelt","c:d/d1/Taddamoute%2C_Morocco_-_panoramio_%281%29.jpg"],["Q647417",29,"ville","Mohammédia","C","Mohammédia, anciennement Fḍala est une ville et commune du Maroc, située dans la banlieue de Casablanca, chef-lieu de la préfecture de Mohammédia, dans la région administrative du Casablanca-Settat et anciennement dans le Grand Casablanca.",117,"fr:Mohammédia","c:2/21/Le_parc_des_villes_jumel%C3%A9es_Mohammedia.jpg"],["Q593222",30,"ville","Moulay Driss Zerhoun","C","Moulay Driss Zerhoun, ou Zerhoun, est une ville de la région de Fès-Meknès, dans le nord du Maroc. Elle s'étend sur deux collines à la base du mont Zerhoun. Elle est célèbre pour être le site du tombeau d'Idris Ier, le premier souverain de la dynastie idrisside, dont la ville tire son nom. Elle est située près de Meknès et surplombe les ruines de Volubilis, à quelques kilomètres de là.","Moulay Driss Zerhoun, ou Zerhoun, est une ville de la région de Fès-Meknès, dans le nord du Maroc.","fr:Moulay_Driss_Zerhoun","c:8/86/Moulay_Idriss%2C_Maroc_%28318486164%29.jpg"],["Q824594",31,"ville","Nador","PC","Nador est une ville marocaine rifaine, située dans la région tribale des Qelaya. Sur le plan préfectoral, Nador fait partie de la province préfectorale de Nador, qui elle-même fait partie de la région préfectorale de Oujda.","Nador est une ville marocaine rifaine, située dans la région tribale des Qelaya.","fr:Nador_(Maroc)","c:8/88/Corniche_de_Nador_%28Marchica%29.jpg"],["Q505208",32,"ville","Ouarzazate","PC","Ouarzazate est une ville et commune — municipalité — de la province de Ouarzazate, dont elle est le chef-lieu, dans la région Drâa Tafilalet. La ville est surnommée « la Porte du désert ».",118,"fr:Ouarzazate","c:0/0f/Kasbah_Taourirt_in_Ouarzazate_2011.jpg"],["Q193802",33,"ville","Oujda","PC","Oujda est une ville du nord-est du Maroc, située dans la plaine de l'Angad, à proximité de la frontière avec l'Algérie. Chef-lieu de la préfecture d'Oujda-Angad et de la région de l'Oriental, elle constitue le principal centre administratif, économique, universitaire et culturel de l'est du pays. Sa population s'élève à 506 224 habitants selon le recensement général de la population et de l'habitat de 2024.","Oujda est une ville du nord-est du Maroc, située dans la plaine de l'Angad, à proximité de la frontière avec l'Algérie.","fr:Oujda","c:6/68/Oujdacol.jpg"],["Q3551",34,"ville","Rabat","E","Rabat est la capitale du royaume du Maroc. La ville est située sur la côte Atlantique, au nord-ouest du Maroc, à quarante kilomètres au sud de Kénitra, à deux-cent-quarante kilomètres au sud-ouest de Tanger et du détroit de Gibraltar et à quatre-vingt-sept kilomètres au nord-est de Casablanca. Elle est séparée de la ville de Salé par l'embouchure du Bouregreg, ce qui vaut aux deux villes le surnom de « villes jumelles ».","Rabat est la capitale du royaume du Maroc.","fr:Rabat","c:d/d9/Rabat_Tour_Hassan.jpg"],["Q27536174",35,"ville","Rissani","C","Rissani est une ville du sud-est du Maroc, près d'Erfoud, porte d'entrée vers les dunes de l'Erg Chebbi et berceau de la dynastie alaouite.","","en:Rissani","c:e/e2/MAUSOL%C3%89E_MOULAY_ALI_CHERIF_-rissani_-maroc.jpg"],["Q183405",36,"ville","Safi","PC","Safi est une ville dans l'ouest du Maroc sur l'océan Atlantique. Capitale de la province de Safi et de l'ancienne région Doukkala-Abda, Safi a une population de 308 508 habitants.","Safi est une ville dans l'ouest du Maroc sur l'océan Atlantique.","fr:Safi","c:c/c8/Safi_1.png"],["Q466046",37,"ville","Salé","PC","Salé est une ville du Maroc, chef-lieu de la préfecture de Salé, au sein de la région de Rabat-Salé-Kénitra. Elle est située au bord de l'océan Atlantique, sur la rive droite de l'embouchure du Bouregreg, dans la banlieue est de la capitale nationale Rabat.","Salé est une ville du Maroc, chef-lieu de la préfecture de Salé, au sein de la région de Rabat-Salé-Kénitra.","fr:Salé","c:c/c8/Monuments_de_Sal%C3%A9.png"],["Q4759",38,"ville","Saïdia","C","Saïdia, surnommée « la perle bleue », est une ville située dans la province de Berkane, dans la région de l'Oriental, au Maroc. La ville est sur le territoire de la tribu arabe rifaine des Beni Mansour, appartenant à la tribu de Triffa. Saïdia est située sur la plaine de Triffa, limitée au sud par la région des Yat Iznassen, à l'est par l'Algérie, à l'ouest par la région des Ikebdanen, et au nord par la Mer méditerranée.",117,"fr:Saïdia","c:a/a3/Saidia%27s_Marina_by_night_-_Berkane_Morocco_by_Brahim_FARAJI.jpg"],["Q818019",39,"ville","Settat","C","Settat est une ville du Maroc faisant partie de la région Casablanca-Settat, chef-lieu de la province de Settat. Elle est située dans la région géographique et historique de la Chaouia. La ville se trouve à 57 km de Casablanca, à environ 34 km au sud de Berrechid et à 40 km au nord de Ben Ahmed, sur la route de Marrakech. En 2014, sa population était de 141 703 habitants.","Settat est une ville du Maroc faisant partie de la région Casablanca-Settat, chef-lieu de la province de Settat.","fr:Settat","c:7/73/Settat_square_downtown_-_MOROCCO.jpg"],["Q632361",40,"ville","Sidi Ifni","PC","Sidi Ifni ou Ifni est une ville marocaine de la région de Guelmim-Oued Noun, située au bord de l'océan Atlantique. Après avoir fait partie de la province de Tiznit, elle est devenue le chef-lieu de la province de Sidi Ifni en 2009, lorsque celle-ci a été créée mais aussi de la tribu berbère des Ait Baâmrane.","Sidi Ifni ou Ifni est une ville marocaine de la région de Guelmim-Oued Noun, située au bord de l'océan Atlantique.","fr:Sidi_Ifni","c:9/98/Ciudad_de_Sidi_Ifni.jpg"],["Q621472",41,"ville","Taghazout","C","Taghazout est une commune rurale de la préfecture d'Agadir Ida-Outanane, dans la région de Souss-Massa, au Maroc.",null,"fr:Taghazout","c:8/87/Blue_fishing_boats_in_Taghazout%2C_Morocco_%288628196631%29.jpg"],["Q126148",42,"ville","Tanger","E","Tanger est une ville du nord du Maroc, capitale de la région de Tanger-Tétouan-Al Hoceïma et chef-lieu de la préfecture de Tanger-Assilah. La ville se situe à l'extrémité du nord-ouest du pays sur le détroit de Gibraltar à quatorze kilomètres de la côte espagnole. Sa population s'élève à 1 275 428 habitants selon le recensement de 2024.",119,"fr:Tanger","c:a/a4/Tanger_cor.jpg"],["Q762727",43,"ville","Taroudant","PC","Taroudant, est une ville du Sud-Ouest du Maroc située dans la plaine du Souss.",null,"fr:Taroudant","c:b/b3/Taroudant_City_Walls_2011.jpg"],["Q574469",44,"ville","Taza","PC","Taza est une ville marocaine située entre le Rif et le Moyen Atlas, dans la région de Fès-Meknès et le chef-lieu de la province de Taza. Elle appartient au Maroc oriental géographiquement et culturellement. Elle se trouve à 114 km de Hoceima, 200 km à l'ouest de Nador et à 117 km à l'est de Fès. Le nom de la ville vient de la langue berbère signifiant: col.",118,"fr:Taza","c:2/20/Taza-maroc-fes-meknes-office-tourisme-maroc.jpg"],["Q335141",45,"ville","Tinghir","C","Tinghir est une ville berbère du Haut Atlas oriental.",null,"fr:Tinghir","c:9/97/Tinghir_village_Ouarzazate_Province.jpg"],["Q587107",46,"ville","Tiznit","C","Tiznit est une ville du centre du Maroc et le chef-lieu de la province de Tiznit, dans la région Souss-Massa. La population de la ville, qui s’élève à 86 595 habitants en 2024, est majoritairement berbère parlant largement le tamazight.","Tiznit est une ville du centre du Maroc et le chef-lieu de la province de Tiznit, dans la région Souss-Massa.","fr:Tiznit","c:0/0d/Tiznit_Logo.jpg"],["Q185157",47,"ville","Tétouan","PC","Tétouan est une ville du Maroc, située dans le nord du pays, dans le Rif occidental, aussi appelé pays Jbala. La ville est située à environ 60 km au sud-est de la ville de Tanger et à proximité du détroit de Gibraltar, dans une vallée creusée par l'oued Mhannech dans les montagnes de la chaîne calcaire du Rif au nord et au sud.","Tétouan est une ville du Maroc, située dans le nord du pays, dans le Rif occidental, aussi appelé pays Jbala.","fr:Tétouan","c:4/4f/Tetouan.jpg"],["Q140354",48,"ville","Zagora","C","Zagora est une ville du Maroc située dans la région de Drâa-Tafilalet. La ville nouvelle de Zagora date du protectorat français dont elle était un des centres administratifs. Toutefois, l'oasis chef lieu de la région du Drâa était habitée depuis bien plus longtemps, puisque c'est de là qu'est partie l'expédition des Saadiens, dynastie de l'Empire chérifien, vers Tombouctou en 1591.","Zagora est une ville du Maroc située dans la région de Drâa-Tafilalet.","fr:Zagora_(Maroc)","c:3/3d/Zagora.jpg"],["Q60539878",49,"lieu","Al Boraq","PC","Al Boraq est le train à grande vitesse de l'Office national des chemins de fer, offre « premium » de la compagnie nationale marocaine; il désigne à la fois le train, la marque déposée et la ligne commerciale sur laquelle le train circule. Par la mise en service commercial de la première ligne à grande vitesse en Afrique le 26 novembre 2018, Al Boraq circule à une vitesse de 320 km/h, ce qui en fait le train le plus rapide de ce continent.",113,"fr:Al_Boraq","c:e/ef/Al_Boraq_RGV2N2_at_Tanger_Ville.jpg"],["Q574853",50,"lieu","Anti-Atlas","C","L'Anti-Atlas, ou Petit Atlas, est une chaîne de montagnes au sud-ouest du Maroc, orientée sud-ouest et nord-est sur près de 800 km, située entre le Haut Atlas central et du Souss au Tafilalet. Cette chaîne appartient au massif de l'Atlas, et plus précisément, à l'un des trois éléments de l'Atlas marocain — les deux autres étant le Haut Atlas et le Moyen Atlas.",115,"fr:Anti-Atlas","c:9/9a/Les_monts_Atlas.png"],["Q130135",51,"lieu","Atlas","E","L'Atlas est un massif montagneux et une cordillère d'Afrique du Nord, culminant à 4 167 mètres au djebel Toubkal, au Maroc. Il s'étend sur trois pays: l'Algérie, le Maroc et la Tunisie.",116,"fr:Atlas_(massif)","c:2/20/AtlasRange.jpg"],["Q2881543",52,"lieu","Bab Boujloud","C","Bab Boujloud ou porte de Bou Jeloud est une des portes de l'ancienne Medina de Fès. C’est l’un des symboles de la ville et de tout le pays. Faisant partie de la médina de Fès, elle est inscrite au patrimoine mondial de l’UNESCO depuis 1981.","Bab Boujloud ou porte de Bou Jeloud est une des portes de l'ancienne Medina de Fès.","fr:Bab_Boujloud","c:5/5d/Fes_Bab_Bou_Jeloud_2011.jpg"],["Q2877688",53,"lieu","Bab Mansour el Aleuj","C","Bab Mansour el-Aleuj, appelée également la porte du Renégat, Bab el-Mansour ou encore Bab Mansour, est la porte de la ville de Meknès au Maroc la plus importante et la plus remarquable. Elle est située en face de la célèbre place Lahdim.",117,"fr:Bab_Mansour_el_Aleuj","c:f/f4/Bab_Mansour_gate.jpg"],["Q772975",54,"lieu","Cap Spartel","C","Le cap Spartel ou ras Spartel est un promontoire de la côte du Maroc, situé à l'entrée sud du détroit de Gibraltar, à 14 kilomètres à l'ouest de Tanger. Face au cap Spartel, à 44 km au nord, le cap Trafalgar marque l'entrée nord du détroit, sur la côte espagnole.",117,"fr:Cap_Spartel","c:b/ba/Lighthouse_after_renovation.jpg"],["Q38212",55,"lieu","Cascades d'Ouzoud","C","Les cascades d'Ouzoud sont des chutes d'eau d'environ 110 m de haut, sur trois paliers, sur un site géologique pittoresque de l'oued Tissakht, à 1 060 m d'altitude du massif de l'Atlas, dans le Haut Atlas central, au Maroc. Ce vaste site est un important lieu touristique marocain, à 15 km d'Azilal, 120 km de Béni Mellal, et 150 km au nord-est de Marrakech.",110,"fr:Cascades_d'Ouzoud","c:a/af/Cascades_d%27Ouzoud_012.JPG"],["Q2314811",56,"lieu","Chellah","C","Le Chellah,, est le site d'une nécropole mérinide située sur l'emplacement d'une cité antique, dans l'actuelle ville de Rabat, au Maroc, à environ 200 m du rempart almohade.",119,"fr:Chellah","c:3/33/Roman_Ruins_Zawiya_Chellah_Rabat_Nov25_A7CR_08989.jpg"],["Q503433",57,"lieu","Djebel Toubkal","PC","Le djebel Toubkal est le point culminant du Haut Atlas, du Maroc et de l'Afrique du Nord avec une altitude de 4 167 m. Il est situé à 63 km au sud de Marrakech, dans la province d'Al Haouz, à l'intérieur du parc national qui porte son nom.","Le djebel Toubkal est le point culminant du Haut Atlas, du Maroc et de l'Afrique du Nord avec une altitude de 4 167 m.","fr:Djebel_Toubkal","c:d/df/Djebel_Toubkal_des_de_Ukaimeden.JPG"],["Q486636",58,"lieu","Drâa","C","Le Drâa, fleuve du Dra ou oued Drâa est le plus long fleuve du Maroc avec 1 100 kilomètres. Sa vallée comporte une partie habitée avec de nombreuses oasis dans le Draa moyen, c'est la « vallée du Drâa » du Maroc touristique, et une partie désertique en aval de Mhamid el Ghizane.","Le Drâa, fleuve du Dra ou oued Drâa est le plus long fleuve du Maroc avec 1 100 kilomètres.","fr:Drâa","c:d/dc/Dra%C3%A2_river.JPG"],["Q36124",59,"lieu","Détroit de Gibraltar","R","Le détroit de Gibraltar est situé au sud de l'Espagne, au nord du Maroc, à l'est de l'océan Atlantique et dans l'Ouest de la mer Méditerranée. C'est le seul passage maritime entre l'océan Atlantique et la mer Méditerranée, dont il constitue la partie la plus occidentale. À son point le plus réduit, il n'est large que de 14,3 km.",118,"fr:Détroit_de_Gibraltar","c:9/9a/Strait_of_Gibraltar_5.53940W_35.97279N.jpg"],["Q146219",60,"lieu","Erg Chebbi","C","L'erg Chebbi, plus connu sous le nom de dunes de Merzouga, est l'un des deux grands ergs du Sahara au Maroc.",null,"fr:Erg_Chebbi","c:2/2d/Erg_Chebbi_pano.jpg"],["Q14517494",61,"lieu","Fondouk","C","Un fonduk, fondouk ou funduq, est « hôtellerie et entrepôt des marchands » que l'on trouve essentiellement au Maghreb et au Moyen-Orient. On utilise aussi le terme caravansérail.",117,"fr:Fondouk","c:0/0a/Fes_-_Fondouk_el-Nejjarine.jpg"],["Q901124",62,"lieu","Gorges du Dadès","C","Les gorges du Dadès sont des gorges situées dans la haute vallée du Dadès entre les localités de Boumalne-Dadès et M'semrir au Maroc. C’est une destination touristique fréquentée.",114,"fr:Gorges_du_Dadès","c:9/98/Gorges_du_dades03.jpg"],["Q3111026",63,"lieu","Gorges du Toudra","C","Les gorges du Toudra sont situées dans le Haut Atlas marocain.",null,"fr:Gorges_du_Toudra","c:f/f2/Togra_Gorge.JPG"],["Q12244393",64,"lieu","Grottes d'Hercule","C","Les grottes d'Hercule sont des cavernes naturelles situées à 14 km à l’ouest de Tanger, au Maroc, à l'entrée atlantique du détroit de Gibraltar.",119,"fr:Grottes_d'Hercule_(Tanger)","c:a/a1/Cuevas_de_H%C3%A9rcules%2C_Cabo_Espartel%2C_Marruecos%2C_2015-12-11%2C_DD_22-24_HDR.JPG"],["Q28077",65,"lieu","Hammam","R","Le hammam, appelé bain turc en France ou bain maure, est un bain de vapeur humide puisant ses origines dans les thermes romains, il a par la suite été adapté aux us et coutumes des différents territoires au sein desquels il a été intégré. Dans sa forme actuelle, le hammam s'est développé dans l'Empire ottoman, de l’Afrique du Nord jusqu'au Moyen-Orient à la faveur de l'expansion de l'islam. Le hammam désigne aussi l'établissement, le bâtiment dans lequel s'organise ce bain.",119,"fr:Hammam","c:a/a4/Aleppo_Citadel_12_-_Hammam.jpg"],["Q584279",66,"lieu","Haut Atlas","PC","Le Haut Atlas est une chaîne montagneuse marocaine orientée sud-ouest/nord-est. Cette chaîne appartient au massif de l'Atlas et plus précisément, à l'un des trois éléments de l'Atlas marocain, les deux autres étant le Moyen Atlas et l'Anti-Atlas.","Le Haut Atlas est une chaîne montagneuse marocaine orientée sud-ouest/nord-est.","fr:Haut_Atlas","c:9/9a/Les_monts_Atlas.png"],["Q1395431",67,"lieu","Jardin Majorelle","PC","Le jardin Majorelle est un jardin botanique touristique d'environ 300 espèces sur près d'un hectare, une villa Art déco labellisée Maisons des Illustres depuis 2011, et un musée de l'Histoire des Berbères, à Marrakech au Maroc.",119,"fr:Jardin_Majorelle","c:5/57/Le_jardin_des_majorelle_16.JPG"],["Q392057",68,"lieu","Jardins de l'Agdal","C","Les jardins de l'Agdal sont les plus anciens jardins de Marrakech, conçus au XIIe siècle sous le règne d'Abd el-Moumen, un souverain almohade.",119,"fr:Jardins_de_l'Agdal","c:c/cf/Agdale.jpg"],["Q89468",69,"lieu","Kasbah","PC","Une kasbah est une citadelle, commune en Afrique du Nord-Ouest, telles la casbah d'Alger, à Rabat, ou la kasbah de Tunis, qui étaient à l'origine des fortifications militaires.",114,"fr:Kasbah","c:d/d2/Alger_algiers_casbah_1900.jpg"],["Q2569036",70,"lieu","Kasbah des Oudayas","PC","La kasbah des Oudaya, ou Oudaïa est un ancien camp militaire fortifié bâti au XIIe siècle par les almohades à Rabat, capitale administrative du Maroc et classé au patrimoine mondial de l'Unesco depuis 2012",116,"fr:Kasbah_des_Oudayas","c:8/85/Kasbah_des_Oudaias_P1060356.JPG"],["Q89691",71,"lieu","Ksar","C","Un ksar, ou ighrem, au pluriel respectivement kosour, et igherman, est un village fortifié d'architecture berbère que l'on trouve en Afrique du Nord.",117,"fr:Ksar_(fortification)","c:3/38/Ksar_Igharghar_11.jpg"],["Q309436",72,"lieu","Ksar d'Aït-ben-Haddou","R","Le ksar d'Aït-ben-Haddou est un ksar au Maroc, situé dans la province de Ouarzazate. Il est inscrit sur la liste du patrimoine mondial de l'UNESCO.","Le ksar d'Aït-ben-Haddou est un ksar au Maroc, situé dans la province de Ouarzazate.","fr:Ksar_d'Aït-ben-Haddou","c:d/d5/Ksar_A%C3%AFt_Benhaddou%2C_Marocco_%28%D8%A3%D9%8A%D8%AA_%D8%A8%D9%86_%D8%AD%D8%AF%D9%88%D8%8C_%D8%A7%D9%84%D9%85%D8%BA%D8%B1%D8%A8%2C_%E2%B4%B0%E2%B5%A2%E2%B5%9C_%E2%B5%83%E2%B4%B0%E2%B4%B7%E2%B4%B7%E2%B5%93%29.jpg"],["Q16593169",73,"lieu","Ksar Taourirt","C","Le Ksar Taourirt est un village fortifié berbère dans la province de Ouarzazate, région de Draa-Tafilalet au sud-est du Maroc.",119,"fr:Ksar_Taourirt","c:3/3b/Ksar_of_Taourirt%2C_Ouarzazate%2C_Morocco_%28%D9%82%D8%B5%D8%A8%D8%A9_%D8%AA%D8%A7%D9%88%D8%B1%D9%8A%D8%B1%D8%AA%2C_%E2%B5%9C%E2%B4%B0%E2%B5%A1%E2%B5%94%E2%B5%89%E2%B5%94%E2%B5%9C%29.jpg"],["Q1394586",74,"lieu","Lagune de Nador","C","La lagune de Nador (en berbère: rebhar Ameẓyan ou Buɛerg; en espagnol: Mar Chica; en darija marocaine: sebkhat Buɛerg) est une lagune de la côte méditerranéenne du Maroc, au Rif, située à proximité des agglomérations de Nador et Beni Ansar et qui forme une continuité avec Melilla, et près de Kariat Arekmane.",118,"fr:Lagune_de_Nador","c:c/cc/Nador-mar_chica1_800x600.jpg"],["Q219028",75,"lieu","Mausolée Mohammed-V","PC","Le mausolée Mohammed-V est un tombeau royal situé à Rabat, capitale du Maroc. Il se trouve sur l'esplanade de la tour Hassan et en surplomb de l'embouchure du fleuve Bouregreg.","Le mausolée Mohammed-V est un tombeau royal situé à Rabat, capitale du Maroc.","fr:Mausolée_Mohammed-V","c:5/50/Morocco_-_Mausoleum_of_Mohammed_V.jpg"],["Q1335801",76,"lieu","Morocco Mall","C","Le Morocco Mall est un centre commercial à Casablanca au Maroc.",null,"fr:Morocco_Mall","c:9/99/Logo_Morocco_Mall.png"],["Q12192954",77,"lieu","Mosquée de Tinmel","C","La mosquée de Tinmal ou grande mosquée de Tinmal est une mosquée du XIIe siècle située dans le village de Tinmel, dans les montagnes du Haut Atlas marocain. Bien qu'elle ne fonctionne plus comme une mosquée aujourd'hui, ses vestiges sont préservés en tant que site historique. Elle a été construite sur le site où Ibn Tumart, le fondateur du mouvement religieux du caliphat Almohade, a été enterré et elle est considérée comme un exemple important de l'architecture archétypale.",118,"fr:Mosquée_de_Tinmel","c:9/99/%D8%A7%D9%84%D9%85%D8%B3%D8%AC%D8%AF_%D8%A7%D9%84%D8%A3%D8%B9%D8%B8%D9%85_%D8%AA%D9%8A%D9%86%D9%85%D9%84_18_%28cropped%29.jpg"],["Q41346",78,"lieu","Mosquée Hassan-II","R","La mosquée Hassan-II est une grande mosquée située à Casablanca. Érigée en partie sur la mer, elle est un complexe religieux et culturel, aménagée sur neuf hectares et comporte une salle de prières, une salle d'ablutions, des bains, une école coranique, une bibliothèque, un musée et une Académie des arts traditionnels.","La mosquée Hassan-II est une grande mosquée située à Casablanca.","fr:Mosquée_Hassan-II","https://upload.wikimedia.org/wikipedia/fr/thumb/f/fc/Mosqu%C3%A9e_Hassan_II_-_2016-04-13.jpg/330px-Mosqu%C3%A9e_Hassan_II_-_2016-04-13.jpg"],["Q1137533",79,"lieu","Mosquée Koutoubia","R","La mosquée Koutoubia est un édifice religieux construit au XIIe siècle à Marrakech, Maroc. Elle est la plus grande mosquée de la ville. Son architecture et son décor ascétique reflètent l'art des Almohades.","La mosquée Koutoubia est un édifice religieux construit au XIIe siècle à Marrakech, Maroc.","fr:Mosquée_Koutoubia","c:d/d9/Kutubiyya_Mosque%2C_2010.jpg"],["Q1146608",80,"lieu","Moulouya","C","La Moulouya ou Melouiya est un fleuve du Maroc qui prend naissance à la jonction du massif du Moyen et du Haut Atlas dans la région d'Almssid dans la province de Midelt. Il est long de 600 km et se jette dans la mer Méditerranée, dans la région du Rif oriental, précisément dans les plaines d'Ikebdanen et Triffa, à l’extrême nord-est du Maroc. Son embouchure est située à 14 km de la frontière algéro-marocaine.",116,"fr:Moulouya","c:e/eb/Moulouya_Marocco.jpg"],["Q1433137",81,"lieu","Moyen Atlas","C","Le Moyen Atlas est un massif montagneux allongé sur quelque 350 km, du sud-ouest au nord-est du Maroc, situé entre le Rif et le Haut Atlas, et couvrant une superficie totale de 2,3 millions d'hectares, soit 18 % du domaine altimontain de ce pays.",117,"fr:Moyen_Atlas","c:9/9a/Les_monts_Atlas.png"],["Q1560540",82,"lieu","Médersa Ben Youssef","PC","La médersa Ben Youssef est une médersa, école coranique. Joyau de l'architecture saadienne, elle est située à Marrakech, au Maroc.","La médersa Ben Youssef est une médersa, école coranique.","fr:Médersa_Ben_Youssef","c:d/d4/Ben_Youseff_Madressa.jpg"],["Q1128906",83,"lieu","Médina","C","Une médina désigne la partie ancienne d'une ville par opposition aux quartiers modernes de type européen. Ce terme est surtout employé dans les pays du Maghreb et dans une moindre mesure au Machrek, en Espagne, en Afrique de l'Ouest, en Afrique de l'Est et dans la Méditerranée, notamment à Malte. En raison de leur patrimoine et des savoir-faire qu'elles abritent, un certain nombre de médinas sont inscrites au patrimoine mondial par l'UNESCO, notamment en Afrique du Nord.","Une médina désigne la partie ancienne d'une ville par opposition aux quartiers modernes de type européen.","fr:Médina","c:3/37/Vue_sur_Tunis.jpg"],["Q11858823",84,"lieu","Médina d'Essaouira","C","La médina d'Essaouira (الصويرة, aṣ-Ṣawirah, Al-Suwayra, en arabe, « la Bien-Dessinée », anciennement Mogador, du phénicien Migdol « petite forteresse », Tassourt ou Amogdul, en berbère, Mogdura, en portugais, Mogadur, en espagnol, Mogador, en français, surnommée « le Saint-Malo marocain », ou la « cité des vents », est une médina marocaine, centre historique d'Essaouira, sur la côte Atlantique du Maroc.",112,"fr:Médina_d'Essaouira","c:3/3b/Ramparts_of_Essaouira.JPG"],["Q2072102",85,"lieu","Médina de Fès","C","La médina de Fès est une médina marocaine, cœur historique de Fès, inscrite depuis 1981 au patrimoine mondial de l'Unesco.",112,"fr:Médina_de_Fès","c:7/74/29628-Fez_%2827596365313%29.jpg"],["Q966780",86,"lieu","Médina de Marrakech","C","La médina de Marrakech est une médina marocaine, cœur historique de Marrakech. Elle forme un des cinq arrondissements que compte la commune urbaine de Marrakech.","La médina de Marrakech est une médina marocaine, cœur historique de Marrakech.","fr:Médina_de_Marrakech","c:7/79/Djemaa_el_Fna.jpg"],["Q3847588",87,"lieu","Médina de Tétouan","C","La Médina de Tétouan est l'ancienne ville islamique de Tétouan, au Maroc. Très caractéristiques et traditionnelles, les maisons de la medina sont presque toutes blanches et basses. Dans toute la médina, on trouve des artisans tels que des tisserands, des bijoutiers et des fourreurs. Il existe également de nombreux vendeurs de rue qui vendent des tapis aux touristes.","La Médina de Tétouan est l'ancienne ville islamique de Tétouan, au Maroc.","fr:Médina_de_Tétouan","c:1/17/Medina_de_Tetouan_Nov2020_054.jpg"],["Q1920259",88,"lieu","Ménara","C","La Ménara est un vaste jardin planté d'oliviers aménagé sous la dynastie des Almoahades à environ 45 minutes à pied de la place Jemaa el-Fna, au centre de Marrakech, au Maroc. Au cœur de ce jardin, un grand bassin au pied d'un pavillon sert de réservoir d'eau pour irriguer les agricultures. C'est un endroit très paisible, à l'écart du tumulte de la ville. C'est donc un lieu privilégié pour les promenades.",118,"fr:Ménara_(jardin)","c:c/c4/Jardins_de_la_M%C3%A9nara.jpg"],["Q1778840",89,"lieu","Oum Errabiâ","C","Oum Errabiâ, anciennement appelé Morbêa est un fleuve marocain. Long de 550 km, il est le deuxième cours d'eau du pays et son débit atteint 117 m3/s.","Oum Errabiâ, anciennement appelé Morbêa est un fleuve marocain.","fr:Oum_Errabiâ","c:1/1a/Sources_d%27Oum_Rabii_1.JPG"],["Q2465115",90,"lieu","Palais de la Bahia","PC","Le palais de la Bahia est un ancien palais du XIXe siècle de huit hectares de style mauresque / islamique, à Marrakech au Maroc. Actuel musée, il est un des chefs-d'œuvre de l'architecture marocaine et de l'art marocain, un des monuments majeurs du patrimoine culturel du pays, et un des principaux lieux de tourisme au Maroc.",118,"fr:Palais_de_la_Bahia","c:f/fc/Bahia_Palace_large_court.jpg"],["Q3042276",91,"lieu","Palais royal","C","Le palais royal de Fès au Maroc Dar el-Makhzen, est un palais situé dans la commune de Méchouar Fès Jdid, à Fès, au Maroc.",115,"fr:Palais_royal_(Fès)","c:b/bf/Fes_-_Palau_Reial_-_Porta_principal.JPG"],["Q784621",92,"lieu","Parc national de Souss-Massa","C","Le parc national de Souss-Massa, créé en 1991, se situe au Maroc dans la région de Souss-Massa, entre Agadir et Tiznit. L'entrée du parc de l'Oued Massa est au bout du village de Sidi-Bnazern. Située à l'embouchure de l'Oued Massa, cette réserve naturelle, d'une superficie de 33 800 hectares, abrite aussi bien les mammifères, comme les mangoustes, chacals, sangliers et gazelles, que des oiseaux, comme les goélands, faucons, cormorans et hérons.","Le parc national de Souss-Massa, créé en 1991, se situe au Maroc dans la région de Souss-Massa, entre Agadir et Tiznit.","fr:Parc_national_de_Souss-Massa","c:a/a7/Oued-Massa-jardins.jpg"],["Q258348",93,"lieu","Place Jemaa el-Fna","PC","La place Jamaa Alfna est une célèbre place publique au sud-ouest de la médina de Marrakech au Maroc. Ce haut-lieu traditionnel, populaire et animé, notamment la nuit, attire plus d'un million de visiteurs chaque année.","La place Jamaa Alfna est une célèbre place publique au sud-ouest de la médina de Marrakech au Maroc.","fr:Place_Jemaa_el-Fna","c:7/79/Djemaa_el_Fna.jpg"],["Q767261",94,"lieu","Riad","PC","Un riad (jardin en arabe: روض, pluriel: رياض) est une demeure urbaine traditionnelle répandue dans le monde arabe, en al-Andalus et plus particulièrement au Maroc disposant d'un patio central ou d'un jardin intérieur. Elles se situent le plus souvent dans les médinas des villes.",117,"fr:Riad","c:7/72/Riad_Maroc_031.JPG"],["Q275491",95,"lieu","Rif","PC","Le Rif — en berbère: ⴰⵔⵉⴼ, Arrif; en arabe: ar-Rif —, est la région septentrionale du Maroc, bordée par la mer Méditerranée au nord, l'Algérie à l'est, les plaines le séparant du Moyen Atlas au sud et l'océan Atlantique à l'ouest. Composé de montagnes et de plaines, le Rif s'étend sur près de 350 km de Tanger jusqu'à la Moulouya.",110,"fr:Rif","c:a/ac/Rif_mountains.png"],["Q391215",97,"lieu","Site archéologique de Volubilis","R","Volubilis est le vestige d'une ville romaine construite sur l'ancien site d'une ville punico-berbère, qui fut capitale du royaume de Maurétanie, située sur le plateau de Volubilis dans la plaine du Saïss, dans le Nord marocain, sur les bords de l'oued Rhoumane, rivière de la banlieue de Meknès, non loin de la ville de Moulay Driss Zerhoun. C'est l'un des sites archéologiques les plus importants du Maroc.",118,"fr:Site_archéologique_de_Volubilis","c:d/de/Volubilis%28js%299.jpg"],["Q510177",98,"lieu","Souk","C","Un souk est un marché forain éphémère du monde arabe, généralement hebdomadaire. C’est aussi un lieu de transactions commerciales. Il est presque toujours en plein air; seuls certains souks des médinas sont parfois couverts. Son équivalent en persan ou turc est le bazar, tandis qu’en tamazight, il est appelé ameznaz, ulzuz ou anmugger et en espagnol zoco.","Un souk est un marché forain éphémère du monde arabe, généralement hebdomadaire.","fr:Souk","c:b/bd/Souk_El_Attarine.jpg"],["Q1783824",99,"lieu","Stade Mohammed-V","C","Le stade Mohammed-V, couramment appelé « Donor », prononciation altérée de son appellation d'origine « stade d'Honneur », est un stade de football situé dans le quartier de Maârif, près du centre-ville de Casablanca. Sa capacité est de 48 000 places assises.",118,"fr:Stade_Mohammed-V","c:5/5c/Mohammed_V_stadium.jpg"],["Q757166",100,"lieu","Studios Atlas","C","Les Studios Atlas sont des studios de cinéma situés à Ouarzazate, au Maroc, et créés en 1983 par Mohamed Belghmi.",null,"fr:Studios_Atlas","c:1/16/Ouazazate.jpg"],["Q518888",101,"lieu","Tanger Med","C","Le Groupe Tanger Med gère le complexe portuaire Tanger Med, doté d’un emplacement stratégique, 1er port en Méditerranée et en Afrique. Il dispose aussi d’une présence nationale grâce au réseau de Marsa Maroc, doté de 24 terminaux à conteneurs et vracs répartis dans 10 ports à travers le Maroc. En 2023, 162 millions de tonnes de marchandises et 9,6 millions de conteneurs EVP ont été traités.",119,"fr:Tanger_Med","c:5/58/Vue_g%C3%A9n%C3%A9raleH13A0659.JPG",{"cats":["maroc","transports"]}],["Q48815525",102,"lieu","Tannerie Chouara","C","La tannerie Chouara est la plus grande et l'une des plus anciennes tanneries de Fès, au Maroc, célèbre pour ses cuves de teinture colorées.","","en:Chouara_Tannery","c:4/46/Chouara_Tannery_-_154_-_Marokko_Handybilder_2018_-_Fes_%2827347707917%29.jpg"],["Q2152745",103,"lieu","Tombeaux saadiens","C","Les Tombeaux saadiens sont une nécropole royale historique à Marrakech, au Maroc. Ils datent de l'époque de la dynastie saadienne, et en particulier du règne d'Ahmad al-Mansur. Ils sont situés immédiatement au sud de la mosquée de la Kasbah, à l'intérieur du quartier royal de la kasbah de la ville. En raison de la beauté de leur décoration, ils constituent une attraction majeure auprès des visiteurs de la ville ocre.","Les Tombeaux saadiens sont une nécropole royale historique à Marrakech, au Maroc.","fr:Tombeaux_saadiens","c:3/3b/Saadian_Tombs_1044-HDR.jpg"],["Q579331",104,"lieu","Tour Hassan","R","La tour Hassan est une tour emblématique de Rabat, capitale du Maroc, constituant le minaret d'une mosquée du XIIe siècle inachevée.",114,"fr:Tour_Hassan","c:8/81/Tour_Hassan-Rabat-2.jpg"],["Q25452628",105,"lieu","Tour Mohammed-VI","PC","La tour Mohammed-VI est une tour dans la commune de Salé, limitrophe de Rabat, capitale du Maroc. Conçue par Othman Benjelloun et construite par l'entreprise O'Tower, elle est la troisième plus haute tour d'Afrique après L'Iconic Tower en Égypte et le minaret Djamaâ El-Djazaïr en Algérie.","La tour Mohammed-VI est une tour dans la commune de Salé, limitrophe de Rabat, capitale du Maroc.","fr:Tour_Mohammed-VI","c:0/09/Burg_Mohammed_6.jpg"],["Q378014",106,"lieu","Université Al Quaraouiyine","R","Al Quaraouiyine est une université située à Fès, au Maroc. Selon la tradition, sa construction débute en 859 sous le règne de la dynastie idrisside.","Al Quaraouiyine est une université située à Fès, au Maroc.","fr:Université_Al_Quaraouiyine","c:7/74/University_of_Al_Qaraouiyine.jpg"],["Q15058332",107,"lieu","Vallée de l'Ourika","C","La vallée de l'Ourika – du nom de la rivière homonyme – est une vallée du Haut Atlas marocain située à 30 km au sud-est de Marrakech.",119,"fr:Vallée_de_l'Ourika","c:6/6a/Ourika_River.jpg"],["Q2843608",108,"plat","Amlou","PC","L'amlou est une préparation culinaire de la région du Souss que les Marocains et particulièrement les Chleuhs ont l'habitude de consommer. Cette pâte à tartiner traditionnelle marocaine se compose d'huile d'argan, d'amandes grillées et peut contenir du miel. C'est un fortifiant qui est servi au petit déjeuner ou au goûter sur du pain d’orge, de maïs ou de blé. Il accompagne aussi toutes sortes de pâtisseries.",113,"fr:Amlou","c:c/c3/ArganAmlou_Oil_Mill.jpg"],["Q2879043",109,"plat","Baghrir","C","Le baghrir, ghrayef, khringo, tibouâjajin, appelé aussi en français crêpes mille trous ou crêpes nid d'abeille est une crêpe répandue au Maghreb préparée à base de semoule ou de farine, de levure et de sel, servie chaude, généralement imbibée de beurre et de miel.",118,"fr:Baghrir","c:a/a0/Beghrir_%28Homemade%29.jpg"],["Q60790164",110,"plat","Batbout","C","Le batbout est un pain traditionnel et très populaire de la cuisine marocaine. C'est un pain plat, rond et légèrement épais, cuit dans une poêle sans huile, ce qui le distingue des autres pains plats cuits au four. Il est souvent servi comme accompagnement lors des repas, notamment avec des tajines, des soupes, des légumes ou des viandes.","Le batbout est un pain traditionnel et très populaire de la cuisine marocaine.","fr:Batbout","c:f/f1/Batbout.jpg"],["Q5729169",111,"plat","Bissara","C","La bissara est un plat à base de fèves ou de pois secs, appartenant à la cuisine marocaine.",null,"fr:Bissara","c:6/67/Thamarakt%2C_pur%C3%A9e_de_pois_cass%C3%A9s_%C3%A0_servir_avec_un_bon_filet_d%27huile_d%27olive..jpg"],["Q4968516",112,"plat","Briouate","C","Le briouate ou briwate est un chausson feuilleté, généralement de forme triangulaire, d'origine ottomane. L'appellation de briouate est restreinte au Maroc et issue du mot brioute turc. Il peut être sucré ou salé.","Le briouate ou briwate est un chausson feuilleté, généralement de forme triangulaire, d'origine ottomane.","fr:Briouate","c:6/6d/Briouat_%28cropped%29.jpg"],["Q1070271",113,"plat","Charmoula","C","La charmoula ou chermoula est une sauce utilisée dans la cuisine berbère au Maghreb, accompagnant le plus souvent du poisson.",116,"fr:Charmoula","c:2/23/Chermoula_tagine.jpg"],["Q2961907",114,"plat","Chebakia","C","La chebakia, appelée également griwech en Algérie ou m'kharqa au Maroc, est une pâtisserie de forme roulée originaire du Maghreb, à base de farine, de matière grasse, de miel et d'eau de fleur d'oranger.",117,"fr:Chebakia","c:b/bd/%D9%83%D8%B1%D9%8A%D9%88%D8%B4.JPG"],["Q2364865",115,"plat","Corne de gazelle","C","La corne de gazelle est une pâtisserie maghrébine en forme de croissant à base d'amandes.",null,"fr:Corne_de_gazelle","c:c/c7/Cornes_de_gazelle.JPG"],["Q1150262",117,"plat","Cuisine marocaine","PC","La cuisine marocaine est une cuisine méditerranéenne caractérisée par sa variété de plats issus principalement de la cuisine berbère, avec des influences arabes, juives et andalouses.",116,"fr:Cuisine_marocaine","c:4/4d/Tajines_in_a_pottery_shop_in_Morocco.jpg",{"cats":["maroc","nourriture"]}],["Q3104931",118,"plat","Ghribiya","C","La ghribiya, est une spécialité pâtissière préparée dans les pays du Maghreb, l’Égypte et dans le Proche-Orient.",null,"fr:Ghribiya","c:0/03/Ghribia_alg%C3%A9rienne.jpg"],["Q5892267",119,"plat","Harcha","C","La harcha est une galette berbère du Maroc et d'Algérie, introduite au Maroc par les boulangers tlemceniens, installés à Fès lors de la colonisation française, qui l'appelaient aussi 'Khobz el Harcha'. Elle est préparée à base de semoule, de beurre et de lait ou d'eau. Cette galette est essentiellement servie avec du thé à la menthe et du miel lors du petit déjeuner ou encore lors des collations.",118,"fr:Harcha","c:c/c8/Ary-7ercha.JPG"],["Q1513612",120,"plat","Harira","PC","La harira est une soupe traditionnelle du Maroc et de l'Algérie d'origine andalouse. Elle est constituée de tomates, de légumes, de viande et d'oignon.","La harira est une soupe traditionnelle du Maroc et de l'Algérie d'origine andalouse.","fr:Harira","c:3/3f/Harira_vegetarisch.jpg"],["Q45418",121,"plat","Huile d'argan","PC","L'huile d'argan ou l'huile d'argane est une huile végétale produite à partir des fruits de l'arganier et riche en vitamine A, vitamine E, en antioxydants et en acides gras essentiels.",113,"fr:Huile_d'argan","c:9/90/Argane_oil_production.jpg"],["Q28495800",122,"plat","Jben","C","Jben est l'appellation au Maghreb pour désigner un type de fromage traditionnel, habituellement préparé avec du lait cru de brebis ou de chèvre.",116,"fr:Jben","c:2/2b/Ary-jben_mak%C3%AAye_Rif_coirbeye.JPG"],["Q752388",123,"plat","Kefta","R","Le kefta, du verbe persan kouftan ou koubidan, « écraser » ou « frapper », est une boulette de viande que l'on sert au Maghreb, au Machrek, dans les Balkans, la Turquie, le Caucase, en Iran, au Pakistan et dans le sous-continent indien.",118,"fr:Kefta","c:a/a2/Sultanahmet_K%C3%B6ftesi.jpg"],["Q2892007",124,"plat","Khlii","C","Le khlii, khlea, ou kleehe, est une préparation culinaire propre à la gastronomie maghrébine, notamment utilisée dans les cuisines algérienne et marocaine, à base de viande aux aromates confite dans de la graisse. Deux variantes consistent à remplacer la graisse par de l'huile d'olive ou du smen, le beurre rance.",117,"fr:Khlii","c:0/04/Moroccan_preserved_dried_meat-Khli-01.jpg"],["Q16654630",125,"plat","Leben","C","Le leben, lben, Ighi ou Aghou, est un babeurre obtenu à partir de lait cru fermenté spontanément. Le beurre et le babeurre sont séparés par barattage. Il ne doit pas être confondu avec le laban levantin, qui est l'appellation locale du yaourt.","Le leben, lben, Ighi ou Aghou, est un babeurre obtenu à partir de lait cru fermenté spontanément.","fr:Leben","c:d/db/Lben_1.jpg"],["Q3260187",126,"plat","Loubia","C","La loubia est un plat populaire maghrébin à base de haricots blancs ou de haricots coco accommodés à la sauce tomate, riche en épices, avec quelques fines herbes par-dessus.",117,"fr:Loubia","c:d/d0/%D9%85%D8%B1%D9%82%D8%A9_%D9%84%D9%88%D8%A8%D9%8A%D8%A7.JPG"],["Q1886522",127,"plat","Makroud","C","Le makroud ou makrout, également orthographié maqroudh ou maqrouth, est une pâtisserie maghrébine, à base de semoule de blé et de pâte de dattes, reconnaissable à sa forme en losange. C'est une pâtisserie très populaire au Maghreb et également à Malte.",119,"fr:Makroud","c:7/7f/Makrouds.JPG"],["Q1754504",128,"plat","Merguez","PC","La merguez est une petite saucisse rouge épicée originaire du Maghreb, d'environ deux centimètres de diamètre et d'une quinzaine de centimètres de longueur, à base d'un hachis de viande et de condiments introduits dans de l'intestin grêle de mouton, et qui se consomme grillée ou frite.",118,"fr:Merguez","c:f/f4/Merguez_grilled.jpg"],["Q16664232",129,"plat","Mhancha","C","La mhancha est une pâtisserie du Maghreb, à base de pâte feuilletée, de forme circulaire, fourrée aux amandes et nappée de miel.",119,"fr:Mhancha","c:1/10/Mhancha_%2Cpatisserie_algerienne.jpg"],["Q3099553",130,"plat","Mrouzia","C","La mrouzia est un plat du Maghreb constitué d'un tajine sucré-salé au mouton ou à l'agneau, accompagné d'amandes et souvent de raisins secs.",115,"fr:Mrouzia","c:e/e9/IB_tajine_02.jpg"],["Q2631911",131,"plat","Msemmen","C","Le msemmen, également orthographié msemen et m'semen, est une sorte de crêpe feuilletée. Spécialité culinaire du Maghreb, on en trouve des variétés différentes selon les régions, notamment en Algérie, au Maroc et en Tunisie.","Le msemmen, également orthographié msemen et m'semen, est une sorte de crêpe feuilletée.","fr:Msemmen","c:d/db/Msemmem.jpg"],["Q1915612",132,"plat","Méchoui","C","Le méchoui est un mets culinaire d’Afrique du Nord composé le plus souvent d’un mouton ou d’un agneau entier rôti à la broche, sur les braises d'un feu de bois. Le mot vient du verbe arabe « šawa » qui signifie « griller », « rôtir ».",118,"fr:Méchoui","c:9/96/Mechoui.jpg"],["Q664137",133,"plat","Pastilla","PC","La pastilla est un plat traditionnel du Maghreb, constitué d'une sorte de feuilleté, à base d'oignon, de pigeons, de persil, de coriandre, d'œuf dur et d'amandes, mélange de sucré et de salé, parfumé à la cannelle. Elle est souvent servie lors des fêtes, juste avant le plat principal.",116,"fr:Pastilla","c:e/ed/Bisteeya.jpg"],["Q1067261",134,"plat","Ras el-hanout","R","Le ras el-hanout, parfois orthographié raz-el-hanout, littéralement « tête de l'épicerie », est un mélange d'épices et d'herbes aromatiques du Maghreb utilisé dans la cuisine maghrébine, présent dans les cuisines du Maroc, d'Algérie, de Tunisie et de Libye. On le trouve en vente chez les marchands d'épices, dans tous les souks, soit moulu, soit à l'état brut. Son prix varie du simple au décuple selon les ingrédients employés. On le nomme parfois curry maghrébin.",118,"fr:Ras_el-hanout","c:a/a2/Ras.el.hanout.jpg"],["Q2654913",135,"plat","Rfissa","PC","La rfissa, également appelée trid, est un mets culinaire, à base de msemmen.",null,"fr:Rfissa","c:5/5f/Rfissa_marocaine.jpg"],["Q3477693",136,"plat","Seffa","C","La seffa, plat marocain et algérien à base de semoule, est un couscous sucré à la cannelle et aux amandes. Au Maroc, il peut aussi être fait avec du riz ou des vermicelles. Ce plat se mange généralement en fin de repas avant le dessert. Il est souvent servi pendant les cérémonies traditionnelles de mariage et les repas de famille.","La seffa, plat marocain et algérien à base de semoule, est un couscous sucré à la cannelle et aux amandes.","fr:Seffa","c:0/0f/Seffa.jpg"],["Q3478195",137,"plat","Sellou","C","Le sellou ou slilou, aussi appelé sfouf, dont une variante est la zammita, est un dessert consommé au Maroc, et qui existe aussi en Algérie.",115,"fr:Sellou","c:8/89/Selou.jpg"],["Q3090471",138,"plat","Sfendj","C","Le sfendj, ou sfenj, est un beignet d'origine maghrebine. Selon les régions, il peut avoir différents noms. C'est un beignet à base de pâte levée, de type pâte à pain, faite de farine ou de semoule très fine, longuement pétrie, ce qui lui donne cet aspect d'éponge à la cuisson.","Le sfendj, ou sfenj, est un beignet d'origine maghrebine.","fr:Sfendj","c:7/74/Sfenj_alg%C3%A9rien.jpg"],["Q2397413",139,"plat","Smen","C","Le smen est un beurre fermenté et salé originaire d'Afrique du Nord et du Proche-Orient.",null,"fr:Smen","c:8/8e/Smen_msemmen.jpg"],["Q27962923",140,"plat","Taktouka","C","La taktouka est une salade berbère marocaine, servie en entrée, elle est traditionnellement composée d'une diversité d'ingrédients tels que les tomates, poivrons, longuement mijotés et confits à l'huile d'olive, généralement assaisonnés d'ail, d'épices, et de plantes herbacées.",116,"fr:Taktouka",""],["Q3515119",141,"plat","Tangia","C","La tangia, tanjia ou tanjia maarakchia, est un plat traditionnel de la cuisine marocaine originaire de la ville de Marrakech, la tanjia est le plat emblématique de la ville. Ce plat est réputé pour être préparé par les hommes.",114,"fr:Tangia","c:f/f4/Tanjia-959.jpg"],["Q937101",142,"plat","Thé à la menthe","PC","Le thé à la menthe (en arabe maghrébin: أتاي, لأتاي ou tay, en berbère du nord: ⴰⵜⴰⵢ, atay, et en tawellemmet: ⵛⵂⴷ, ecehid) est une boisson chaude originaire du Maghreb, réalisée à partir de feuilles de thé vert gunpowder et de feuilles de menthe. Son aire géographique de répartition traditionnelle s'étend à l'ensemble du Maghreb.",115,"fr:Thé_à_la_menthe","c:e/e2/Moroccan_cups_of_tea_with_ment.jpg"],["Q6170718",143,"plat","Zaalouk","C","Le zaalouk ou zaâlouk ou zaâlouka est une spécialité culinaire traditionnelle des cuisines marocaine et algérienne à base d'aubergines, de tomates, d'herbes aromatiques, d'épices et d'huile d'olive.",116,"fr:Zaalouk","c:4/45/Zaalouk_03.jpg"],["Q2635155",144,"tradition","Ahidous","C","L’ahidous, parfois appelé selon les régions haydous, tahidoust, hidoussi, désigne un art d’expression musicale berbère aussi bien masculin que féminin. C'est une danse traditionnelle pratiquée par les Berbères du Moyen Atlas et du Haut-Atlas au Maroc, ainsi que par quelques tribus du sud du Rif, dans laquelle hommes et femmes, coude à coude, forment des rondes souples et ondulantes, accompagnées de chants rythmés par l'alloun.",118,"fr:Ahidous","c:3/36/COLLECTIE_TROPENMUSEUM_Dansgroep_Midden_Atlas_TMnr_10028646.jpg"],["Q4696445",145,"tradition","Ahouach","C","L'ahouach est une danse traditionnelle collective berbère du sud marocain. Les danseurs d'ahwach sont appelés ihouaouyn","L'ahouach est une danse traditionnelle collective berbère du sud marocain.","fr:Ahouach","c:3/31/Ahwach_Aoulouz.png"],["Q56426",146,"tradition","Arabe marocain","PC","L'arabe marocain, appelé au Maroc « al-darija al-maghribiya» arabe: الدارجة المغربية, est une langue-toit rassemblant plusieurs variétés d'arabe dialectal parlées au Maroc. Il appartient au groupe des dialectes maghrébins.",117,"fr:Arabe_marocain","c:5/5f/Morocco_-_Linguistic_map.png",{"cats":["maroc","langues"]}],["Q379746",147,"tradition","Arganier","C","L’Arganier ou Argania spinosa L. (en berbère chleuh: ⴰⵔⴳⴰⵏ ou ⵜⴰⵔⴳⴰⵏⵜ, en arabe maghrébin: أرݣان ou ارڨان) est une espèce de plantes à fleurs de la famille des Sapotaceae. C'est un arbre qui se caractérise par un tronc court, souvent noueux, avec des branches basses et des feuilles épineuses.","L’Arganier ou Argania spinosa L.","fr:Arganier","c:2/25/Huile_d%27argan_003.JPG"],["Q211232",148,"tradition","Armoiries du Maroc","C","Les armoiries du Maroc sont utilisées principalement par le roi du Maroc, mais également comme armoiries nationales par l'État marocain. Elles ont été adoptées le 14 août 1957, la veille du jour où le sultan Sidi Mohammed ben Youssef devient officiellement le premier roi du Maroc, sous le nom de Mohammed V.",119,"fr:Armoiries_du_Maroc","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Coat_of_arms_of_Morocco.svg/330px-Coat_of_arms_of_Morocco.svg.png"],["Q514400",149,"tradition","Aïd al-Adha","R","L'aïd al-Adha également appelée, dans les pays du Maghreb, aïd el-Kebir (عيد الكبير,, « grande fête », par opposition à l'aïd el-Fitr également appelée, dans les pays du Maghreb, aïd as-Seghir ou « petite fête »), est la plus importante des fêtes musulmanes. Elle est appelée Tabaski dans les pays d'Afrique de l'Ouest et d'Afrique centrale, Tafaska chez les amazighophones en Afrique du Nord, Bayram en Asie de l'Est, et Ghorban dans les pays persanophones.",119,"fr:Aïd_al-Adha","c:9/9a/Bovino_para_sacrificio_de_Eid_al-Adha.jpg",{"cats":["maroc","religions","fetes"]}],["Q410117",150,"tradition","Aïssawa","C","Les Aïssawa sont une confrérie et un ordre mystico-religieux soufi marocain, fondés par Sidi Mhammed ben Aïssâ, surnommé le « Maître Parfait ». Le terme Aïssawa est aussi utilisé pour désigner une forme musicale rituelle et folklorique marocaine typique de la ville de Mèknes.",111,"fr:Aïssawa","c:c/c9/Aissawa_Fes_Morocco.event_traditional_folklore_In_PortraitDSC03878.JPG"],["Q22949256",151,"tradition","Aïta","C","L'aïta est un genre musical et poétique populaire marocain. Cet art vocal collectif est interprété par des chanteurs et chanteuses, respectivement appelés chioukhs et cheikhates. Elle combine poésie orale, musique instrumentale et performance scénique, et occupe une place centrale dans le patrimoine culturel immatériel du Maroc.","L'aïta est un genre musical et poétique populaire marocain.","fr:Aïta",""],["Q3180074",152,"tradition","Babouche","C","La babouche est une chaussure en cuir, traditionnelle dans le monde musulman.",null,"fr:Babouche","c:6/67/Babouches_maroc.jpg"],["Q45315",153,"tradition","Berbères","L","Les Berbères, ou Amazighs, sont un groupe ethnique, autochtone d'Afrique du Nord. Connus dans l'Antiquité sous le nom de Libyens, les Berbères ont porté différents noms durant l'histoire, tels que Mazices, Maures, Numides, Gétules, Garamantes et autres. Ils sont répartis dans une zone s'étendant de l'océan Atlantique à l'oasis de Siwa en Égypte, et de la mer Méditerranée au fleuve Niger en Afrique de l'Ouest. Cette zone s'étend sur près de cinq millions de kilomètres carrés.","Les Berbères, ou Amazighs, sont un groupe ethnique, autochtone d'Afrique du Nord.","fr:Berbères","c:a/a9/Berb%C3%A8res_des_quatre_coins_d%27Afrique_du_nord.jpg"],["Q2932927",154,"tradition","Caftan","PC","Le caftan est une tunique longue portée dans diverses régions à travers le monde, entre autres au Moyen-Orient, au Maghreb, en Asie centrale, en Perse, dans l'Empire moghol sous la dynastie fondée par Babur, dans certains États indépendants italiens comme la république de Venise, dans l'Empire omeyyade et l'Empire ottoman, et dans certaines régions d'Afrique subsaharienne. Le terme recouvre une grande variété de tuniques longues existant ou ayant existé à différentes époques.",114,"fr:Caftan","c:9/9b/Kurd_Man.png"],["Q2961759",155,"tradition","Chaâbi marocain","C","Le chaâbi marocain est un ensemble de genres musicaux populaires marocain. On le retrouve dans les plaines atlantiques ainsi que dans le Moyen Atlas.","Le chaâbi marocain est un ensemble de genres musicaux populaires marocain.","fr:Chaâbi_marocain","c:4/42/NajatAatabou1.jpg"],["Q60515006",156,"tradition","Coupe d'Afrique des nations de football 2025","E","La Coupe d'Afrique des nations de football 2025 est la 35e édition du tournoi biennal de football des associations africaines organisé par la Confédération africaine de football. Elle s'est déroulée du 21 décembre 2025 au 18 janvier 2026 au Maroc.",114,"fr:Coupe_d'Afrique_des_nations_de_football_2025","https://upload.wikimedia.org/wikipedia/fr/thumb/2/21/Coupe_d%27Afrique_des_nations_de_football_2025_logo.svg/330px-Coupe_d%27Afrique_des_nations_de_football_2025_logo.svg.png"],["Q14935989",157,"tradition","Coupe du monde de football 2030","M","La Coupe du monde de football 2030 ou Coupe du monde de la FIFA 2030 est la 24e édition de la Coupe du monde de football, compétition organisée par la FIFA et disputée par les meilleures sélections nationales masculines.",111,"fr:Coupe_du_monde_de_football_2030","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/FIFA_World_Cup_wordmark_%282023%29.svg/330px-FIFA_World_Cup_wordmark_%282023%29.svg.png"],["Q319154",158,"tradition","Darbouka","C","La darbouka est un instrument de percussion à son déterminé faisant partie des membranophones. Selon ses variantes, c'est un vase étranglé en son milieu et recouvert à l'une de ses extrémités d'une membrane, répandu dans toute l'Afrique du Nord, l'Afrique subsaharienne, le Moyen-Orient et les Balkans.","La darbouka est un instrument de percussion à son déterminé faisant partie des membranophones.","fr:Darbouka","c:b/bb/Goblet_drum_01.jpg",{"cats":["maroc","instruments"]}],["Q2652461",159,"tradition","Derby de Casablanca","C","Le Derby de Casablanca se réfère à l'antagonisme entre les deux plus grands clubs de football au Maroc, tous les deux basés à Casablanca: le Raja Club Athletic et le Wydad Athletic Club. Se déroulant traditionnellement au Stade Mohammed-V, c'est considéré comme l'un des derbys les plus intenses du monde.",117,"fr:Derby_de_Casablanca","c:8/85/Wydad_Casablanca_vs_Raja_de_Casablanca%2C_April_10_2011-4.jpg"],["Q200192",160,"tradition","Dirham marocain","PC","Le dirham marocain est la monnaie officielle du Royaume du Maroc, sur le plan international, émise par la Bank Al-Maghrib. Il est divisé en 100 centimes de dirham.",110,"fr:Dirham_marocain","c:a/a0/Dirhams_marocains_%28MAD%29.jpeg"],["Q182064",161,"tradition","Djellaba","PC","La djellaba ou jellaba /d͡ʒɛlaba/ est une longue robe ample avec un capuchon, portée par les hommes et les femmes, répandue comme vêtement traditionnel au Maghreb.",114,"fr:Djellaba","c:a/ad/Morocco%2C_djellaba%2C_end_of_20th_century_-_Bunka_Gakuen_Costume_Museum_-_DSC05317.JPG"],["Q1395855",163,"tradition","Fantasia","C","La fantasia est une tradition équestre pratiquée essentiellement au Maghreb — incluant le Maroc, l'Algérie, la Tunisie et la Libye —, se manifestant par la simulation d'assauts militaires. Cet art est notamment appelé « jeu de la poudre » ou « jeu des chevaux », et porte divers noms en fonction des régions, dont tbourida au Maroc.",118,"fr:Fantasia_(cavalerie)","c:6/63/Fantasia_%C3%A0_Ain_Larba.jpg"],["Q3070337",164,"tradition","Festival Gnaoua et Musiques du monde","C","Le Festival Gnaoua et Musiques du Monde est un festival de musique marocain créé en 1998 afin de mettre en valeur la culture des Gnaoua. Il se tient chaque année au mois de juin dans la ville d’Essaouira, rassemblant des artistes du Maroc et d’ailleurs pour célébrer la diversité musicale, le patrimoine immatériel et les traditions spirituelles gnaouies.",116,"fr:Festival_Gnaoua_et_Musiques_du_monde","c:7/74/Le_festival_gnaoui_favorise_louverture_et_la_tol%C3%A9rance_%287851916574%29.jpg"],["Q3070717",165,"tradition","Festival international du film de Marrakech","C","Le Festival international du film de Marrakech est un festival de cinéma organisé annuellement à Marrakech, depuis 2001.",null,"fr:Festival_international_du_film_de_Marrakech","c:4/45/Martin_Scorsese_y_Leonardo_DiCaprio.jpg"],["Q3045874",166,"tradition","Festival Mawazine","C","Le Festival Mawazine est un événement musical majeur qui se tient chaque année à Rabat et Salé, au Maroc, depuis 2001. Créé sous l'impulsion de l'association Maroc Cultures, il célèbre la diversité musicale mondiale en réunissant des artistes de renommée internationale et des talents émergents.","Le Festival Mawazine est un événement musical majeur qui se tient chaque année à Rabat et Salé, au Maroc, depuis 2001.","fr:Festival_Mawazine","c:3/34/Mawazine_f%C3%AAte_son_dixi%C3%A8me_anniversaire_dans_un_climat_de_controverses_%285781618927%29.jpg"],["Q189862",167,"tradition","Fez","R","Le fez ou tarbouche est un couvre-chef masculin en feutre, souvent rouge, en forme de cône tronqué, orné d'un gland noir fixé sur le dessus. Ce bonnet sans bord, originaire de la Grèce antique, a été adopté par de nombreux groupes ethniques et religieux pendant les siècles suivants et notamment dans l'Empire ottoman du XIXe siècle.",115,"fr:Fez_(coiffure)","c:9/90/Fez.jpg"],["Q20393998",168,"tradition","Fête du Trône","C","La Fête du Trône au Maroc est un événement national qui est célébré le 30 juillet de chaque année, entrecoupé de plusieurs cérémonies officielles et populaires, qui correspond à l'anniversaire de l'intronisation du roi et de son allégeance officielle. Cette date correspond au jour d'intronisation officielle de l'actuel Mohammed VI le 30 juillet 1999.",112,"fr:Fête_du_Trône","c:8/8e/Roi_Mohammed.jpg"],["Q1533184",169,"tradition","Gnaoua","C","Le Gnaoua, désigne à la fois un style musical du Maghreb et les membres d'origine d'Afrique subsaharienne, principalement des descendants d'esclaves, rassemblés au Maghreb dans des confréries musulmanes mystiques dans lesquelles la transe et les rites de possession jouent un rôle très important.",106,"fr:Gnaoua","c:7/7b/Les_Gnaoua_du_Maroc_par_Brutus_Art.jpg"],["Q1431454",170,"tradition","Guembri","C","Le guembri, est un instrument de musique à cordes pincées des Gnaouas. Il est principalement utilisé en Afrique du Nord au Maroc, en Algérie, en Tunisie et au Mali. Il est aussi joué par les Touaregs et les Berbères. C'est un dérivé du n'goni africain.","Le guembri, est un instrument de musique à cordes pincées des Gnaouas.","fr:Guembri","c:8/86/Guimbri_player%2C_Marrakech.jpg"],["Q124818651",171,"tradition","Hamadsha","C","Les Hamadsha sont une confrérie soufie marocaine qui pratique des rituels de transe musicale, notamment autour de Meknès.","","en:Hamadsha",""],["Q182448",172,"tradition","Henné","PC","Le henné, également connu sous les noms de mehndi, mendhi, mehendi, ḥenna, lḥenni ou anella, est une espèce de plantes à fleurs de la famille des Lythracées. C'est un arbuste épineux pouvant atteindre plusieurs mètres de haut. Ses feuilles sont principalement utilisées comme colorant ou tatouage mais la tradition lui octroie également d'autres vertus, notamment des propriétés médicinales.",118,"fr:Henné","c:1/15/Lawsonia_inermis_Ypey36.jpg"],["Q2672654",173,"tradition","Histoire des Juifs au Maroc","PC","L'histoire des Juifs au Maroc est très ancienne et fut nourrie par diverses vagues de réfugiés à la suite des vicissitudes et persécutions dont ont été victimes les Juifs au cours de l’histoire.",109,"fr:Histoire_des_Juifs_au_Maroc","c:f/f6/Maroc_juif_-_Mekn%C3%A8s_1920.jpg"],["Q238826",174,"tradition","Hymne national","PC","L'hymne du Maroc, (en tamazight: ⵉⵣⵍⵉ ⴰⵏⴰⵎⵓⵔ Izli Anamur, en arabe: النشيد الوطنيAn-našid Al-waṭani; « Hymne national » ou « Hymne chérifien », est une composition musicale composée du temps du protectorat qui a été fixée par un dahir de début 2005. La musique a été composée par le français Léo Morgan et les paroles ont été écrites par Ali Squalli Houssaini.",119,"fr:Hymne_national_(Maroc)","c:1/17/Partition_de_l%27hymne_du_Maroc.gif"],["Q2566690",175,"tradition","Islam au Maroc","C","L'islam est la religion la plus pratiquée au Maroc. Elle y est décrétée religion d'État en 698 par le général arabe Oqba Ibn Nafaa et son armée de berbères Iluwaten. On compte près de 38,03 millions de musulmans marocains pour 38,11 millions, soit 99,8%, ce qui en fait, en 2024, le deuxième pays avec le plus haut taux de musulmans dans le monde, derrière les Maldives avec 100% de musulmans.","L'islam est la religion la plus pratiquée au Maroc.","fr:Islam_au_Maroc","https://upload.wikimedia.org/wikipedia/fr/thumb/f/fc/Mosqu%C3%A9e_Hassan_II_-_2016-04-13.jpg/330px-Mosqu%C3%A9e_Hassan_II_-_2016-04-13.jpg"],["Q25448",176,"tradition","Langues berbères","E","Les langues berbères et leurs dialectes — ou le tamazight, ou encore « le » berbère, en berbère « tamazight » — forment une branche de la famille des langues afro-asiatiques et couvrent une vaste aire géographique: l’Afrique du Nord depuis le Maroc jusqu’à l’Égypte, en passant par l’Algérie, la Tunisie et la Libye, ainsi qu'une partie du Sahara, et la partie ouest du Sahel. Un dialecte du berbère, le guanche, fut parlé autrefois aux îles Canaries.",119,"fr:Langues_berbères","c:e/e4/Map_of_Berber_languages.png",{"cats":["maroc","langues"]}],["Q221094",177,"tradition","Lion de l'Atlas","E","Le lion de l'Atlas, également appelé lion de Barbarie, est une sous-espèce de lions, aujourd'hui éteinte à l'état sauvage. On le trouvait autrefois dans toute l'Afrique du Nord. Les derniers spécimens sauvages ont disparu vers le milieu du XXe siècle. Moins d'une centaine de lions de l'Atlas subsistent en captivité.",113,"fr:Lion_de_l'Atlas","c:4/43/Barbary_lion.jpg"],["Q199962",178,"tradition","Macaque de Barbarie","PC","Le macaque de Barbarie, également appelé magot ou macaque berbère, est une espèce de singes catarhiniens de la famille des cercopithécidés.",118,"fr:Macaque_de_Barbarie","c:7/75/Barbary_macaque_in_Cap_Carbon_%28Gouraya_National_Park%29.jpg"],["Q870684",179,"tradition","Marche verte","PC","La Marche verte est une grande marche coordonnée par l'armée et le gouvernement marocain, et partie du Maroc le 6 novembre 1975 vers le Sahara espagnol — aujourd'hui Sahara occidental —, lancée par le roi marocain Hassan II dans le but d'en prendre le contrôle, car considéré par le Maroc comme faisant historiquement partie du Sahara marocain.",113,"fr:Marche_verte","c:2/2a/Gr%C3%BCner_Marsch_Karte.png"],["Q3305039",180,"tradition","Melhoun","C","Melhoun est un mot arabe qui regroupe toute la poésie populaire écrite en arabe maghrébin qu'elle soit nomade ou citadine. Il désigne l'état de la langue arabe qui sert à l’expression de certaines formes de poésie dialectale au Maghreb, ainsi que cette poésie elle-même.",112,"fr:Melhoun","c:f/f2/%D8%A7%D9%84%D9%85%D9%84%D8%AD%D9%88%D9%86_-_%D9%84%D8%A7%D9%84%D8%A7_%D8%BA%D9%8A%D8%AB%D8%A9_%D9%85%D9%88%D9%84%D8%A7%D8%AA%D9%8A_-_%D8%B9%D8%AF%D9%86%D8%A7%D9%86_%D8%A7%D9%84%D8%B3%D9%81%D9%8A%D8%A7%D9%86%D9%8A.webm"],["Q1884005",181,"tradition","Moussem","C","Le moussem, appelé également waada dans certaines régions d’Algérie, agdud en berbère ou mouggar dans le sud-ouest du Maroc, désigne en Afrique du Nord une fête régionale annuelle qui associe une célébration coutumière, qui peut parfois être religieuse à des activités festives et commerciales.",117,"fr:Moussem",""],["Q623904",182,"tradition","Musique arabo-andalouse","C","La musique arabo-andalouse ou musique « andalouse » ou bien musique mauro-andalouse, aussi appelée al musiqa al andalusiya, ou en Algérie, gharnati, sanâa et malouf pour les variantes régionales et aroubi, chaâbi, hawzi pour les genres dérivés, tarab al-ala ou tarab al-andaloussi au Maroc, malouf en Tunisie et en Libye est un genre musical profane, classique ou savant, du Maghreb, distinct de la musique arabe classique pratiquée au Moyen-Orient et en Égypte.",111,"fr:Musique_arabo-andalouse","c:a/a5/Had%C3%AEth_Bay%C3%A2d_wa_Riy%C3%A2d_-_BAV_Ar368_f10r_-_Garden_scene.jpg"],["Q1051514",183,"tradition","Raja Club Athletic","R","Le Raja Club Athletic abrégé en RCA est un club professionnel marocain de football basé à Casablanca, et l'une des sections du club omnisports éponyme, le Raja Club Athletic.",114,"fr:Raja_Club_Athletic","https://upload.wikimedia.org/wikipedia/fr/thumb/8/85/Logo_Raja_Club_Athletic.svg/330px-Logo_Raja_Club_Athletic.svg.png"],["Q866103",185,"tradition","Royal Air Maroc","R","Royal Air Maroc (en arabe: الخطوط الملكية المغربية; en berbère: ⴰⵎⵓⵏⵉ ⴰⵢⵍⴰⵍ ⴰⴳⵍⴷⴰⵏ ⵏ ⴰⵎⵓⵔⴰⴽⵓⵛ), également appelée RAM, est la compagnie aérienne nationale du Maroc, fondée le 29 juin 1957. Sa principale plate-forme de correspondance est située à l’aéroport Mohammed-V de Casablanca. Elle dessert de nombreuses destinations en Afrique, en Europe, en Amérique et en Asie. Son code IATA est AT et son code OACI est RAM. Elle est certifiée IOSA par l’IATA et fait partie de l’alliance Oneworld.",118,"fr:Royal_Air_Maroc","https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Logo_Royal_Air_Maroc.svg/330px-Logo_Royal_Air_Maroc.svg.png"],["Q1357903",186,"tradition","Tadelakt","C","Le tadelakt ou tadellakt est un enduit-stuc traditionnel de la culture du Maroc, et de l'artisanat marocain, lisse, doux, imperméable, fongicide, et brillant, à base de chaux de Marrakech, d'eau de chaux, et de savon noir, teinté de pigments colorés, traditionnellement utilisé pour étanchéifier les citernes d'eau, ou en artisanat d'art et arts décoratifs, pour enduire et étanchéifier des fontaines, bassins, piscines, vasques, éviers, hammams, salles de bains, des sols, murs, toits, et des façades, de riads, ou de…",115,"fr:Tadelakt","c:1/1f/Sgraffito_tadelakt-minoeco.jpg"],["Q865004",187,"tradition","Tajine","R","Un tajine ou tagine ou tadjine est tout autant un plat de cuisson et de service, en terre cuite, large et peu profond surmonté d'un couvercle parfois vernissé qui peut ou non être conique, qu'une préparation culinaire de type ragoût cuite dans cet ustensile.",117,"fr:Tajine","c:6/6d/Tajine_008.JPG",{"cats":["maroc","nourriture"]}],["Q3514246",188,"tradition","Takchita","C","La takchita est un mot marocain qui désigne une version du caftan marocain revisité par les stylistes marocains. Traditionnellement constituée de deux pièces portées l'une sur l'autre, elle peut en comporter jusqu'à cinq.","La takchita est un mot marocain qui désigne une version du caftan marocain revisité par les stylistes marocains.","fr:Takchita","c:d/db/Moroccan_women_wearing_takchita_%281939%29.jpg"],["Q3515483",189,"tradition","Tapis berbère","C","Le tapis berbère est une sorte de tapis tissé par les Berbères en Afrique du Nord. Ayant plusieurs appellations dépendant de la région on trouve Taṛakna ou encore Taẓerbit.","Le tapis berbère est une sorte de tapis tissé par les Berbères en Afrique du Nord.","fr:Tapis_berbère","c:2/23/Berber_carpet_%285338347185%29.jpg"],["Q208503",190,"tradition","Tifinagh","R","Le tifinagh est l’écriture utilisée par les Berbères pour écrire le tamazight. Elle est dérivée des écritures originelles des langues berbères du Sud algérien et du Niger chez les Touaregs, le libyque initialement désigné sous le terme de numidique — tombée en désuétude pour les langues berbères du Nord dès l'Antiquité — probablement par le biais du tifinagh ancien du Sahara, dont il garde les caractéristiques morphosyntaxiques.","Le tifinagh est l’écriture utilisée par les Berbères pour écrire le tamazight.","fr:Tifinagh","c:8/89/Kidal.jpg",{"cats":["maroc","langues"]}],["Q1139095",191,"tradition","Wydad Athletic Club","R","Le Wydad Athletic Club, généralement appelé Wydad AC ou WAC, est un club de football marocain basé à Casablanca, section football existant depuis 1939 au sein du club omnisports de même nom fondé le 8 mai 1937. Depuis 2002 le Wydad compte par ailleurs une équipe féminine de football.",112,"fr:Wydad_Athletic_Club_(football)","https://upload.wikimedia.org/wikipedia/fr/thumb/4/4d/Logo_Wydad_AC_2022.svg/330px-Logo_Wydad_AC_2022.svg.png"],["Q3572171",192,"tradition","Yennayer","C","Yennayer est la fête du nouvel an amazigh, célébrée à travers l’Afrique du Nord et dans les diasporas maghrébines. Elle est associée au calendrier berbère traditionnel, un calendrier agraire de type solaire apparenté au calendrier julien.","Yennayer est la fête du nouvel an amazigh, célébrée à travers l’Afrique du Nord et dans les diasporas maghrébines.","fr:Yennayer","c:3/32/Berber_Calendars.jpg"],["Q189046",193,"tradition","Zellige","PC","Le zellige, zliz, zellij, zellidj ou encore jelliz suivant les régions, est un type de mosaïque ornementale dans le domaine de l'architecture islamique. Les éléments unitaires, appelés « tesselles », sont des morceaux de carreaux de faïence colorés monochrome artisanaux. Ces morceaux de terre cuite émaillées sont découpés un à un et assemblés sur un lit de mortier pour former un assemblage géométrique polychrome. Il décore aussi bien les monuments religieux que les palais et certaines habitations privées.",115,"fr:Zellige","c:2/2a/Zellige-Marrakesh-1.JPG"],["Q111535594",195,"tradition","Équipe du Maroc de football à la Coupe du monde 2022","C","L'équipe du Maroc de football participe à la Coupe du monde de football 2022 organisée au Qatar du 20 novembre au 18 décembre 2022.",116,"fr:Équipe_du_Maroc_de_football_à_la_Coupe_du_monde_2022","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Flag_of_Morocco.svg/330px-Flag_of_Morocco.svg.png"],["Q199688",196,"histoire","Almohades","R","Les Almohades (en arabe: الْمُوَحِّدُون, en berbère: ⵉⵎⵡⴻⵃⵃⴷⴻⵏ, littéralement en arabe « qui proclame l’unité divine ») sont un mouvement religieux berbère qui se structure ensuite en organisation politique. En 1147, après la capture de Marrakech, il devient un califat berbère qui supplante la dynastie almoravide et qui gouverne le Maghreb et Al-Andalus jusqu'en 1269.",119,"fr:Almohades","https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Almohad_dynasty_en.svg/330px-Almohad_dynasty_en.svg.png"],["Q75613",197,"histoire","Almoravides","R","Les Almoravides sont une dynastie berbère sanhajienne, qui constitua du XIe au XIIe siècle une confédération tribale, un mouvement politico-religieux, puis un empire englobant le Maroc, le Sahara occidental, la Mauritanie, une partie du Mali moderne et l'ouest de l'Algérie, ainsi que le sud de la péninsule Ibérique.",117,"fr:Almoravides","c:6/63/Almoravides_XIIe_si%C3%A8cle.png"],["Q4851214",198,"histoire","Années de plomb","C","Les années de plomb, au Maroc, correspondent à une période de l'histoire contemporaine de ce pays qui s'est étendue des années 1960 jusqu'à 1999 sous le règne du roi Hassan II, et a été marquée par une violence et une répression contre les opposants politiques et les activistes démocrates.",119,"fr:Années_de_plomb_(Maroc)","c:9/9b/Families_gathering_at_the_tombs_of_victims_of_the_Years_of_Lead_following_their_identification_by_the_IER.png"],["Q569394",199,"histoire","Attentats de Casablanca du 16 mai 2003","C","Les attentats de Casablanca sont une série de cinq attentats suicides terroristes qui se déroulent le 16 mai 2003 dans la ville marocaine de Casablanca. Ils sont perpétrés par douze terroristes originaires du bidonville Sidi Moumen, membres de Salafia, et des binationaux franco-marocains et franco-turc des Yvelines sont également impliqués. Le bilan s'élève à 33 victimes et une centaine de blessés.",118,"fr:Attentats_de_Casablanca_du_16_mai_2003","c:a/a3/May_16_memorial_%28cropped%29.png"],["Q1138460",200,"histoire","Bataille d'Anoual","PC","La bataille d’Anoual, connue comme le désastre d’Anoual dans l’historiographie espagnole, est une grave défaite subie entre le 22 juillet et le 9 août 1921 par l’armée espagnole lors de son offensive dans le Rif et, a contrario, une importante victoire pour les milices armées rifaines commandées par Abdelkrim el-Khattabi.",117,"fr:Bataille_d'Anoual","c:d/d3/Guerra_del_Rif_1922_-_2.jpg"],["Q1121532",201,"histoire","Bataille des Trois Rois","PC","La bataille des Trois Rois, bataille de l'oued al-Makhazin ou bataille de l'Alcazar Kébir a été une bataille décisive ayant mis fin au projet d'invasion du Maroc du roi portugais Sébastien Ier en se soldant par la victoire du sultanat marocain. Elle eut lieu sur les rives de l'Oued al-Makhazin, affluent du Loukos iriguant Ksar El Kébir dans la province de Larache.",117,"fr:Bataille_des_Trois_Rois","c:c/c1/Lagos46_kopie.jpg"],["Q163573",202,"histoire","Conférence d'Algésiras","C","La conférence d'Algésiras, donnant lieu aux accords d'Algésiras, est une conférence internationale relative à l'Empire chérifien, dans la ville d'Algésiras en Espagne, du 16 janvier au 7 avril 1906, sous l'égide des États-Unis.",118,"fr:Conférence_d'Algésiras","c:8/86/Conf%C3%A9rence_d%27Alg%C3%A9siras_%28cl._Bringer%29.jpg"],["Q502093",203,"histoire","Conférence de Casablanca","C","La conférence de Casablanca, ou conférence d'Anfa, fut une conférence interalliée qui eut lieu du 14 au 24 janvier 1943 à l'hôtel Anfa de Casablanca au Maroc afin de préparer la stratégie des Alliés après la Seconde Guerre mondiale.",119,"fr:Conférence_de_Casablanca","c:a/a7/Franklin_D._Roosevelt%2C_Churchill%2C_Giraud%2C_and_DeGaulle_in_Casablanca_-_NARA_-_196990.jpg"],["Q17176607",204,"histoire","Constitution marocaine de 2011","C","La Constitution marocaine de 2011 est l'actuelle norme juridique suprême du royaume marocain. Elle est la sixième constitution marocaine, les précédentes datant de 1962, 1970, 1972, 1992 et 1996.","La Constitution marocaine de 2011 est l'actuelle norme juridique suprême du royaume marocain.","fr:Constitution_marocaine_de_2011",""],["Q164771",205,"histoire","Coup d'Agadir","PC","Le coup d'Agadir, ou crise d'Agadir, est un incident militaire et diplomatique qui eut lieu en 1911, entre la France et l'Allemagne, provoqué par l'envoi d'une canonnière de la marine de guerre allemande dans la baie d'Agadir au Maroc, la SMS Panther. Il s'inscrit dans la rivalité des impérialismes européens pour le partage de l'Afrique et la mise en tutelle du Maroc précolonial.",119,"fr:Coup_d'Agadir","c:4/41/SMS_Panther.gif"],["Q167455",206,"histoire","Crise de Tanger","C","La crise de Tanger est une crise internationale opposant en 1905 les puissances européennes au sujet de la colonisation du Maroc, qui sera réglée, dans un premier temps, par la conférence d'Algésiras et la démission, à la demande de l’Allemagne, de l’inamovible ministre français des Affaires étrangères, Théophile Delcassé.",119,"fr:Crise_de_Tanger","c:9/97/Guglielmo_II_a_Tangeri_%281905%29.jpg"],["Q1129036",207,"histoire","Dynastie alaouite","R","La dynastie alaouite — ou les Alaouites, Alawites — est la dynastie régnante du Maroc. Son représentant actuel est Mohammed VI, roi du Maroc.","La dynastie alaouite — ou les Alaouites, Alawites — est la dynastie régnante du Maroc.","fr:Dynastie_alaouite","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Coat_of_arms_of_Morocco.svg/330px-Coat_of_arms_of_Morocco.svg.png"],["Q12183875",208,"histoire","Empire chérifien","PC","L'Empire chérifien (en arabe: المملكة المغربية الشريفة ou الدولة المغربية الشريفة, en amazighe: ⵜⴰⵎⵏⴽⴷⴰ ⵜⴰⵛⵉⵔⵉⴼⵉⵜ ⵏ ⵍⵎⵖⵔⵉⴱ) est le nom porté par le Maroc jusqu'en 1957. Il désigne un ensemble multiethnique et multiconfessionnel mouvant dirigé par la dynastie alaouite.",115,"fr:Empire_chérifien","c:0/0a/Le_Maroc_en_1797.png"],["Q766437",209,"histoire","Guerre du Rif","R","La guerre du Rif est une succession de conflits armés qui a eu lieu de 1921 à 1927 et a opposé d’un côté les troupes coloniales espagnoles, auxquelles se sont jointes en 1924 les troupes françaises et chérifiennes, et de l’autre les tribus berbères de la région montagneuse du Rif.",116,"fr:Guerre_du_Rif","c:8/89/Infobox_collage_for_Rif_War.jpg"],["Q472658",210,"histoire","Histoire du Maroc","R","L'histoire du Maroc et de son territoire remonte aux premiers peuplements du Paléolithique inférieur, dont certaines des plus anciennes traces ont été mises au jour à Djebel Irhoud. Durant l'Antiquité, la région connaît successivement des influences phéniciennes puis carthaginoises, parallèlement à l'émergence de royaumes berbères, notamment le royaume de Maurétanie. Une partie du territoire est ensuite annexée à l'Empire romain et intégrée à la province de Maurétanie tingitane.",116,"fr:Histoire_du_Maroc","c:d/df/Hassan_II%2C_Marrakech%2C_1966.jpg"],["Q431575",211,"histoire","Idrissides","PC","Les Idrissides sont une dynastie arabe chérifienne de souche alide, ayant régné sur l'actuel Maroc et certaines parties de l'ouest de l'Algérie actuelle.",119,"fr:Idrissides","c:e/e5/Mapa_pol%C3%ADtico_de_Marrocos_%28s%C3%A9c._VIII-XI%29.gif"],["Q60845731",212,"histoire","Manifeste de l'indépendance","C","Le Manifeste du 11 janvier 1944 ou Manifeste de l'Indépendance du Maroc est un acte grandement symbolique au Maroc, qui consolide et formalise les prises de position nationalistes issues du Manifeste contre le Dahir berbère du 28 août 1930. Le 11 janvier est officiellement jour férié au Maroc.",119,"fr:Manifeste_de_l'indépendance","c:8/88/%D9%88%D8%AB%D9%8A%D9%82%D8%A9_%D8%A7%D9%84%D8%A7%D8%B3%D8%AA%D9%82%D9%84%D8%A7%D9%84_11_%D9%8A%D9%86%D8%A7%D9%8A%D8%B1_1944.jpg"],["Q1244742",213,"histoire","Maurétanie tingitane","C","La Maurétanie tingitane était une province romaine de l'Empire romain.",null,"fr:Maurétanie_tingitane","c:6/6e/Mauretanie_Tingitane.jpg"],["Q3326647",214,"histoire","Mouvement du 20 Février","C","Le mouvement du 20 février; arabe: حركة 20 فبراير) est un mouvement de contestation apparu au Maroc le 20 février 2011, à la suite de la vague de protestations et de révolutions dans d'autres pays de l'Afrique du Nord et du Moyen-Orient connue sous le nom de « Printemps arabe ».",119,"fr:Mouvement_du_20_Février","c:1/15/20February.jpg"],["Q194132",215,"histoire","Opération Torch","E","L'opération Torch est le nom de code donné au débarquement des Alliés le 8 novembre 1942 en Afrique française du Nord, principalement au Maroc et en Algérie.",118,"fr:Opération_Torch","c:a/af/OPERATION-TORCH-OVERVIEW.png"],["Q457242",216,"histoire","Protectorat espagnol au Maroc","R","Le protectorat espagnol au Maroc (en arabe: حماية إسبانيا في المغرب; en espagnol: protectorado español en Marruecos) est le régime de tutelle qui fut exercé par l'Espagne dans l'Empire chérifien. Mis en place par la convention franco-espagnole de Madrid du 27 novembre 1912, il faisait notamment suite au traité franco-marocain du 30 mars 1912, signé à Fès, qui avait institué le « protectorat français au Maroc »; d'autres tractations, surtout occidentales, parfois secrètes, y ayant mené, tout comme pour le…",116,"fr:Protectorat_espagnol_au_Maroc","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Protectorado_espa%C3%B1ol_en_Marruecos.svg/330px-Protectorado_espa%C3%B1ol_en_Marruecos.svg.png"],["Q907234",217,"histoire","Protectorat français au Maroc","R","Le protectorat français au Maroc ou protectorat français dans l’Empire chérifien est le protectorat qui est exercé par la France dans l’Empire chérifien. Ce protectorat se place plus largement au sein de l’Empire colonial français. On désigne parfois d’« Afrique française du Nord », l’ensemble géographique constitué avec l’Algérie française et le protectorat français de Tunisie.",118,"fr:Protectorat_français_au_Maroc","https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Maroc_sans_cadre.svg/330px-Maroc_sans_cadre.svg.png"],["Q309272",218,"histoire","Royaume de Maurétanie","R","La Maurétanie, ou royaume de Maurétanie, est un ancien royaume berbère établi dans l'actuel nord du Maroc et issu d'une fédération des tribus maures allant de l'océan Atlantique à l'ouest jusqu'à la Moulouya à l'est, frontière étendue, au début du Ier siècle av. J.-C., à l'Oued-el-Kebir dans l'actuel Est de l'Algérie.",119,"fr:Royaume_de_Maurétanie","c:9/9e/Numide.png"],["Q37102",219,"histoire","République du Rif","PC","La république du Rif était un État autoproclamé et non reconnu internationalement, établi dans les montagnes du Rif au Maroc, entre 1921 et 1926, sous la conduite d'Abdelkrim el-Khattabi.",118,"fr:République_du_Rif","c:8/83/Map_of_the_Rif_Republic_at_its_maximum_extension_and_distribution_of_the_Rif_people.jpg"],["Q6755512",220,"histoire","Révolution du Roi et du Peuple","C","La Révolution du Roi sur le Peuple est, dans l'histoire du Maroc, la suite d'événements qui virent notamment les autorités coloniales françaises tentées de placer Mohammed ben Arafa sur le trône alaouite.",112,"fr:Révolution_du_Roi_et_du_Peuple","c:c/cf/Marrocoprotectorate.png"],["Q1136188",221,"histoire","Saadiens","PC","Les Saadiens ou Zaydanides est une dynastie d'origine arabe qui règne sur le Maroc de 1549 à 1659 et dont la capitale est Marrakech.",117,"fr:Saadiens","c:e/e5/Saadiens_-_Carte_fin_XVIe_si%C3%A8cle_%28revised%29.jpg"],["Q582861",223,"histoire","Sultanat mérinide","PC","Le sultanat mérinide ou marinide est un État du Maghreb al-Aqsa fondé par la dynastie mérinide, ou Beni Merin, d'origine berbère zénète. La dynastie règne de 1244 à 1465 et se trouve, à son apogée, à la tête d'un territoire incluant des portions de la péninsule Ibérique, le Maghreb central et l'Ifriqiya. Le sultanat est toutefois marqué par de grandes difficultés à maintenir le contrôle des territoires zianides et hafsides.",110,"fr:Sultanat_mérinide","c:c/c8/Carte_Zianides_au_Maghreb.png"],["Q698056",224,"histoire","Séisme de 1960 à Agadir","C","Le séisme de 1960 à Agadir est un séisme qui s'est produit à Agadir, au Maroc, le 29 février 1960 à 23 h 40, tuant près de 12 000 personnes et faisant quelque 25 000 blessés. La secousse dura 15 secondes et était d'une magnitude de 5,7 sur l'échelle de Richter.",119,"fr:Séisme_de_1960_à_Agadir","c:d/d4/1960_02_29_Agadir_earthquake.png"],["Q122351413",225,"histoire","Séisme de 2023 au Maroc","PC","Le séisme de 2023 au Maroc ou séisme d'Al Haouz, survenu le 8 septembre 2023 à 23 h 11 min 2,2 s UTC, est le plus important tremblement de terre enregistré par des stations sismiques de l'histoire du pays, avec une magnitude qui atteint Mw= 6,7 à 6,9.",113,"fr:Séisme_de_2023_au_Maroc","c:3/39/M_6.8_-_Morocco_ShakeMap_8_Sept_2023.jpg"],["Q3497642",226,"histoire","Zone internationale de Tanger","R","La zone internationale de Tanger est un territoire autonome de 373 km2 ayant existé à Tanger et ses alentours du 14 mai 1924 jusqu'à sa réintégration dans le royaume du Maroc le 29 octobre 1956, avec un statut spécial jusqu'au 11 avril 1960, et un intermède durant la Seconde Guerre mondiale.",119,"fr:Zone_internationale_de_Tanger","https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Maroc_sans_cadre.svg/330px-Maroc_sans_cadre.svg.png"],["Q2821003",227,"personnalite","Abdelaziz Stati","C","Abdelaziz Al Arbaoui, appelé Abdelaziz Stati est natif du village de Al Aounat et « steti » à cause du sixième petit doigt que comporte sa main gauche, est un chanteur marocain de chaâbi, né en 1961 à Al Aounat, dans la province d'El Jadida. Berger durant son enfance, c'est maintenant un spécialiste de la kamanja, un violon avec archet et une caisse de résonance aplatie en forme de huit.",116,"fr:Abdelaziz_Stati","c:0/04/Stati-Fest_Dakhla_2009.JPG"],["Q307921",228,"personnalite","Abdelilah Benkirane","R","Abdelilah Benkirane, né le 8 avril 1954 à Rabat, est un entrepreneur, universitaire et homme d'État marocain, membre du Parti de la justice et du développement. Il est chef du gouvernement du 29 novembre 2011 au 5 avril 2017.",119,"fr:Abdelilah_Benkirane","c:4/40/Abdelilah_Benkirane_2014-08-05.jpg"],["Q202650",229,"personnalite","Abdelkrim el-Khattabi","PC","Muhammad Ben ‘Abd al-Krim al-Khattabi, né vers 1882 à Ajdir, dans le Rif, et mort le 6 février 1963 au Caire, est un homme politique et dirigeant militaire marocain. Il est le chef du mouvement de résistance contre l'Espagne et la France lors de la guerre du Rif. Il est connu sous le nom Emir ‘Abd al-Krim ou ‘Abd al-Krim en Occident, ‘Abd al-Krim al-Khattabi au Maroc ou encore Moulay Mohand chez les Rifains.",116,"fr:Abdelkrim_el-Khattabi","c:9/9b/Mohammed_Abd_al-Karim_%281882%E2%80%931963%29_Presidente_de_la_Republica_del_Rif_1921%E2%80%931927.jpg"],["Q2821160",230,"personnalite","Abdellatif Laâbi","C","Abdellatif Laâbi, né à Fès en 1942, est un poète, écrivain et traducteur marocain. Il a fondé en 1966 la revue Souffles qui jouera un rôle considérable dans le renouvellement culturel au Maghreb.","Abdellatif Laâbi, né à Fès en 1942, est un poète, écrivain et traducteur marocain.","fr:Abdellatif_Laâbi","c:1/1e/Abdellatif_La%C3%A2bi-2011.jpg"],["Q2821209",231,"personnalite","Abdelwahab Doukkali","C","Abdelwahab Doukkali ou Doukali, né le 2 janvier 1941 à Fès et mort le 8 mai 2026 à Casablanca, est un chanteur et compositeur marocain.",113,"fr:Abdelwahab_Doukkali","c:6/6a/Abdelwahab_Doukali_5.jpg"],["Q455739",232,"personnalite","Abu Yusuf Yaqub al-Mansur","C","Abu Yusuf Yaʿqub ibn Yusuf, plus connu sous le nom de Yaʿqub al-Mansur, né en 1160 et mort en 1199 à Marrakech, est le troisième calife almohade. Il succède à son père Abu Yaʿqub Yusuf mort lors du siège de Santarém en 1184, et règne jusqu'à sa mort.",118,"fr:Abu_Yusuf_Yaqub_al-Mansur","c:b/bd/The_Disgrace_of_Averroes_-_Vies_Des_Savants_Illustr%C3%A9s.jpg"],["Q400911",234,"personnalite","Ahmed al-Mansour","C","Abou Abbas Ahmed al-Mansour, surnommé Moulay ad-Dhahbî, est le sixième sultan de la dynastie saadienne, au Maroc, de 1578 à sa mort en 1603.",116,"fr:Ahmed_al-Mansour","c:2/23/AhmadAl-MansurbyAndr%C3%A9Thevet.png"],["Q2842431",235,"personnalite","Ahmed Soultan","C","Ahmed Soultan est un chanteur marocain chleuh né le 17 juin 1978 à Taroudant.",null,"fr:Ahmed_Soultan","c:b/b9/Hatim_Naji_and_Ahmed_Soultan.JPG"],["Q26034345",236,"personnalite","Amine Harit","PC","Amine Harit, né le 18 juin 1997 à Pontoise, est un footballeur international marocain qui évolue au poste d'ailier gauche à l'Olympique de Marseille.",114,"fr:Amine_Harit","c:c/cd/Harit.jpg"],["Q42948040",237,"personnalite","Ayoub El Kaabi","PC","Ayoub El Kaabi, né le 25 juin 1993 à Casablanca, est un footballeur international marocain, évoluant au poste d'avant-centre à l'Olympiakos.",109,"fr:Ayoub_El_Kaabi","c:7/74/Ayoub_El_Kaabi_France_v_Morocco_9_July_2026-131.jpg"],["Q1638114",238,"personnalite","Aziz Akhannouch","E","Aziz Akhannouch, né le 16 août 1961 à Tafraout, est un homme politique et homme d'affaires marocain qui occupe le poste de chef du gouvernement du 7 octobre 2021 au 16 octobre 2026.",119,"fr:Aziz_Akhannouch","c:b/b0/Aziz_Akhannouch_%28cropped%29.jpg"],["Q108109586",239,"personnalite","Azzedine Ounahi","PC","Azzedine Ounahi, né le 19 avril 2000 à Casablanca, est un footballeur international marocain qui évolue au poste de milieu central au Panathinaïkós.",115,"fr:Azzedine_Ounahi","c:5/5d/Azzedine_Ounahi_Morocco_v_Norway_7_June_2026-37.jpg"],["Q264657",240,"personnalite","Badou Zaki","C","Badou Zaki est un footballeur international marocain né le 2 avril 1959 à Sidi Kacem au Maroc. Il a été gardien de but des Lions de l'Atlas. Il est actuellement le sélectionneur de l’équipe nationale de la Jordanie.","Badou Zaki est un footballeur international marocain né le 2 avril 1959 à Sidi Kacem au Maroc.","fr:Badou_Zaki","c:4/48/%D8%A8%D8%A7%D8%AF%D9%88_%D8%A7%D9%84%D8%B2%D8%A7%D9%83%D9%8A.jpg"],["Q368711",241,"personnalite","Badr Hari","R","Badr Hari, — né le 8 décembre 1984 à Amsterdam, est un kick-boxeur néerlando-marocain combattant dans la catégorie des poids-lourds.",118,"fr:Badr_Hari","c:8/8c/Badr-hari-2017-2.jpg",{"cats":["maroc","combat"]}],["Q105955374",242,"personnalite","Bilal El Khannouss","PC","Bilal El Khannouss, né le 10 mai 2004 à Strombeek-Bever, est un footballeur international marocain qui évolue au poste de milieu offensif ou milieu relayeur au VfB Stuttgart.",118,"fr:Bilal_El_Khannouss","c:4/4a/Bilal_El_Khannouss_vs_Niger_%28cropped%29.jpg"],["Q26973015",243,"personnalite","Brahim Díaz","E","Brahim Abdelkader Díaz, généralement appelé Brahim Díaz, né le 3 août 1999 à Malaga en Espagne, est un footballeur international marocain qui évolue au poste de milieu offensif ou d'ailier gauche au Real Madrid.",114,"fr:Brahim_Díaz","c:9/96/Brahim_Diaz_Morocco_v_Norway_7_June_2026-36.jpg"],["Q2821028",244,"personnalite","Douzi","C","Douzi, ou Cheb Douzi, nom de scène d'Abdelhafid Douzi, né le 30 avril 1985 à Oujda, est un chanteur de raï et acteur maroco-belge.",116,"fr:Douzi","c:4/49/Douzi_Image_Official.jpg"],["Q379960",245,"personnalite","Driss Chraïbi","C","Driss Chraïbi, né le 15 juillet 1926 à El Jadida, au Maroc, et mort le 1er avril 2007 à Valence, dans le département de la Drôme, en France, est un écrivain marocain de langue française, auteur d'une vingtaine de romans. Il a également créé des émissions radiophoniques pour France Culture pendant 40 ans.",119,"fr:Driss_Chraïbi","c:4/49/ChraibiDriss.jpg"],["Q107453223",246,"personnalite","ElGrandeToto","C","ElGrandeToto ou Toto ou EGT, de son vrai nom Taha Fahssi, né le 3 août 1996 à casablanca, est un rappeur et chanteur marocain.",116,"fr:ElGrandeToto","c:7/73/ElGrandeToto2-683x1024.jpg"],["Q113506942",247,"personnalite","Eliesse Ben Seghir","PC","Eliesse Ben Seghir, né le 16 février 2005 à Gassin, est un footballeur international marocain qui évolue au poste d'ailier gauche ou de milieu offensif au Bayer Leverkusen.",113,"fr:Eliesse_Ben_Seghir","c:7/70/Eliesse_Ben_Seghir_vs_Niger_%28cropped_2%29.jpg"],["Q109327842",248,"personnalite","Ez Abde","E","Abdessamad Ezzalzouli, dit Ez Abde, né le 17 décembre 2001 à Béni Mellal au Maroc, est un footballeur international marocain jouant au poste d’ailier au Real Betis.",115,"fr:Ez_Abde","c:6/66/Abdessamad_Ezzalzouli_Morocco_v_Norway_7_June_2026-38.jpg"],["Q56281603",249,"personnalite","Faouzia","L","Faouzia Ouihya, dite Faouzia, est une auteure-compositrice-interprète et musicienne marocaine, née le 5 juillet 2000 à Casablanca.",118,"fr:Faouzia_(chanteuse)","c:8/84/Faouzia_at_2026_Montreux_Jazz_Festival-7.jpg"],["Q182363",250,"personnalite","Fatima al-Fihriya","PC","Fatima al-Fihriya, surnommée Omm-al-bannine ou Omm-al-Cassim, est née vers 800 à Kairouan en Tunisie et morte en 880 à Fès, elle aurait fondé l'université Al Quaraouiyine à Fès, au Maroc, qui est considérée comme la 2e plus ancienne université au monde encore en activité.",118,"fr:Fatima_al-Fihriya","c:e/e9/Fatima_Fihria_%28cropped%29.jpg"],["Q242376",251,"personnalite","Fatima Mernissi","C","Fatima ou Fatema Mernissi, en arabe: فاطمة مرنيسي, née en 1940 à Fès et morte le 30 novembre 2015 à Rabat, est une universitaire, sociologue et féministe marocaine.",114,"fr:Fatima_Mernissi","https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Fatima_Mernissi_2004_Al_Azm_Mernissi_Soroush_Mernissi_cropped.tiff/330px-Fatima_Mernissi_2004_Al_Azm_Mernissi_Soroush_Mernissi_cropped.tiff.png"],["Q22689045",252,"personnalite","Fnaïre","C","Fnaïre est un groupe de hip-hop marocain, originaire de Marrakech. Formé en 2001, il est composé de trois chanteurs: Mohcine Tizaf, Khalifa Mennani, et Achraf Aarab. Le quatrième membre du groupe, Hicham Belkas, trouve la mort dans un accident de la circulation survenu à Fès en 2008.","Fnaïre est un groupe de hip-hop marocain, originaire de Marrakech.","fr:Fnaïre",""],["Q1455261",253,"personnalite","French Montana","L","French Montana de son vrai nom Karim Kharbouch, né le 9 novembre 1984 à Casablanca, est un rappeur, producteur et entrepreneur maroco-américain. Il est le fondateur du label Coke Boys Music, et de son prédécesseur Cocaine City Records. En 2012, il signe un contrat de coentreprise avec Bad Boy Records et Maybach Music Group. Il est connu pour ses collaborations avec des artistes tels que Harry Fraud, Max B, Rick Ross, Diddy et les membres de MMG et Bad Boy comme Chinx, Lil Durk, et son frère Zack.",113,"fr:French_Montana","c:e/e9/FM_PRESS03-A.png"],["Q327456",255,"personnalite","Hakim Ziyech","R","Hakim Ziyech né le 19 mars 1993 à Dronten, est un footballeur international marocain qui évolue au poste d'ailier droit ou de milieu offensif au Botafogo FR.",119,"fr:Hakim_Ziyech","c:e/e1/Hakim_Ziyech_2021.jpg"],["Q81120980",256,"personnalite","Hamid El Kasri","C","Hamid El Kasri est un musicien marocain de gnaoua, considéré comme un maâlem (maître), connu pour sa voix puissante.","","en:Hamid_El_Kasri","c:4/45/Hamid_el_Kasri.jpg"],["Q119960944",257,"personnalite","Hamza Igamane","PC","Hamza Igamane, né le 2 novembre 2002 à Témara au Maroc, est un footballeur international marocain qui évolue au poste d'avant-centre au LOSC Lille.",117,"fr:Hamza_Igamane","c:8/85/Hamza_Igamane_vs_Niger_%28cropped%29.jpg"],["Q1996204",258,"personnalite","Hasna du Maroc","C","Lalla Hasna, née le 19 novembre 1967 à Rabat, est une princesse marocaine, membre de la famille royale. Elle est la plus jeune fille du roi Hassan II et de son épouse, Lalla Latifa. Lalla Hasna est la sœur du roi actuel, Mohammed VI.","Lalla Hasna, née le 19 novembre 1967 à Rabat, est une princesse marocaine, membre de la famille royale.","fr:Hasna_du_Maroc","c:4/4f/PrincessLallaHasna_CROP.jpg"],["Q276961",259,"personnalite","Hassan du Maroc","E","Le prince Moulay El Hassan, également appelé Hassan, Al-Hassan, ou El-Hassan ben Mohammed, né le 8 mai 2003 à Rabat, est un membre de la famille royale marocaine, prince héritier du Maroc, en tant que fils aîné du roi Mohammed VI et de la princesse Lalla Salma.",116,"fr:Hassan_du_Maroc","c:f/f9/Pedro_S%C3%A1nchez_se_re%C3%BAne_con_el_rey_de_Marruecos%2C_Mohamed_VI_%286%29_%28cropped%29.jpg"],["Q3128141",260,"personnalite","Hassan Hakmoun","C","Hassan Hakmoun est un musicien gnawa du Maroc. Il est influencé depuis les années 1990 par d'autres musiciens comme Adam Rudolph et Don Cherry. Il allie musique jazzy et musique gnawa, en incluant des rythmes électroniques.","Hassan Hakmoun est un musicien gnawa du Maroc.","fr:Hassan_Hakmoun","c:d/d0/HassanHakmoun.jpg"],["Q69103",261,"personnalite","Hassan II","E","Hassan II, né le 9 juillet 1929 à Rabat et mort le 23 juillet 1999 dans la même ville, est le vingt-et-unième monarque de la dynastie alaouite du Maroc, et le deuxième à porter le titre de roi après son père Mohammed V, du 26 février 1961 à sa mort.",118,"fr:Hassan_II","c:7/7a/Hassan_II_%281983%29.jpg"],["Q2557847",262,"personnalite","Hassan Kachloul","C","Hassan Kachloul est un footballeur franco-marocain né le 19 février 1973 à Agadir au Maroc. Il évoluait au poste de milieu offensif.","Hassan Kachloul est un footballeur franco-marocain né le 19 février 1973 à Agadir au Maroc.","fr:Hassan_Kachloul","c:1/10/Kachloul%2C_Hassan.jpg"],["Q3128286",263,"personnalite","Hatim Ammor","C","Hatim Ammor, né le 29 août 1981 à Casablanca au Maroc, est un chanteur marocain. Il est devenu célèbre grâce à sa victoire lors de la 5e édition de l'émission Studio 2M.","Hatim Ammor, né le 29 août 1981 à Casablanca au Maroc, est un chanteur marocain.","fr:Hatim_Ammor","c:5/55/Hatim_Ammor_discusses_perseverance_%D8%AD%D8%A7%D8%AA%D9%85_%D8%B9%D9%85%D9%88%D8%B1_%D9%8A%D8%AA%D8%AD%D8%AF%D8%AB_%D8%B9%D9%86_%D8%A7%D9%84%D9%85%D8%AB%D8%A7%D8%A8%D8%B1%D8%A9_Hatim_Ammor_pr%C3%B4ne_la_pers%C3%A9v%C3%A9rance.jpg"],["Q83905",264,"personnalite","Hicham El Guerrouj","PC","Hicham El Guerrouj, né le 14 septembre 1974 à Berkane, est un athlète marocain spécialiste des courses de fond et de demi-fond. Il est considéré comme le meilleur athlète marocain de tous les temps.",116,"fr:Hicham_El_Guerrouj","c:2/2b/Hicham_El_Guerrouj_cropped.jpg"],["Q463514",265,"personnalite","Hindi Zahra","C","Hindi Zahra, de son vrai nom Zahra Hindi, née le 20 juin 1979 à Khouribga au Maroc, est une chanteuse, artiste-peintre, autrice, actrice et compositrice franco-marocaine. Elle vit en France depuis 1993.",119,"fr:Hindi_Zahra","c:a/a1/Hindi_Zahra_%40_le_Chabada%2C_Angers_%284315967453%29.jpg"],["Q7331",266,"personnalite","Ibn Battûta","E","Ibn Battûta, de son nom complet ʾAbu ʿAbd Allah Muḥammad Ibn ʿAbd Allah al-Lawātī aṭ-Ṭanjī Ibn Baṭṭūṭa, né le 24 février 1304 à Tanger et mort en 1368 à Fès ou Marrakech, est un explorateur et voyageur d'origine berbère qui aurait parcouru plus de 120 000 km entre 1325 et 1349, de l'ancien territoire du khanat bulgare de la Volga au nord, jusqu'à Tombouctou au sud, et de Tanger à l’ouest jusqu'à Quanzhou en Extrême-Orient.",112,"fr:Ibn_Battûta","c:a/a4/Bust_of_Ibn_Battuta_at_Ibn_Battuta_museum.jpg",{"cats":["maroc","personnalites"]}],["Q438601",267,"personnalite","Idris Ier","C","Idrīs Ier ou Idriss Ier ou Moulay Idriss al-Akbar, mort entre 791 et 793 à Volubilis, est un chérif d'origine arabe, issu de la branche hassanide des Alides, fondateur d'un État idrisside au Maghreb occidental.",116,"fr:Idris_Ier","c:4/4f/Tombeau_de_Moulay_Idriss_1er.jpg"],["Q116995547",268,"personnalite","Ilyas Chaira","C","Ilyas Chaira, né le 2 février 2001 à Ripoll, est un footballeur hispano-marocain qui évolue au poste d'attaquant au Real Oviedo.",115,"fr:Ilyas_Chaira",""],["Q98784065",269,"personnalite","Ismael Saibari","E","Ismael Saibari, de son nom complet Ismael Saibari Ben El Basra, né le 28 janvier 2001 à Terrassa en Espagne, est un footballeur international marocain qui joue au poste de milieu de terrain au Bayern Munich.",115,"fr:Ismael_Saibari","c:a/ac/Ismael_Saibari_2_vs_Niger_%28cropped%29.jpg"],["Q276938",270,"personnalite","Ismaïl ben Chérif","PC","Moulay Ismaïl, ou éventuellement Moulay Ismaïl ben Chérif, né vers 1645 à Sijilmassa et mort le 22 mars 1727 à Meknès, est le sultan du Maroc qui a régné de 1672 à 1727. Septième fils de Moulay Chérif, il exerce la fonction de gouverneur du Nord du Maroc à partir de 1667, jusqu'à la mort de son demi-frère le sultan Moulay Rachid, en 1672.",118,"fr:Ismaïl_ben_Chérif","c:b/b2/Ismail_Ibn_Sharif.jpg"],["Q3178681",272,"personnalite","Jil Jilala","C","Jil Jilala est un groupe de musique marocain créé en 1972. À l'origine, il s'inscrit dans un répertoire musical inspiré de musique folk.","Jil Jilala est un groupe de musique marocain créé en 1972.","fr:Jil_Jilala",""],["Q609626",273,"personnalite","Larbi Ben Barek","C","Larbi Ben Barek, né le 16 juin 1917 à Casablanca et mort le 16 septembre 1992 dans la même ville, est un footballeur marocain, international français.",116,"fr:Larbi_Ben_Barek","c:4/48/Larbi_Ben_Barek_1938.png"],["Q20011526",274,"personnalite","Lartiste","C","Lartiste, nom de scène de Youssef Akdim, est un chanteur, rappeur, auteur-compositeur-interprète et acteur franco-marocain chleuh, né le 4 juillet 1985 à Imintanoute au Maroc.",106,"fr:Lartiste","c:3/3a/Rapper_Lartiste.jpg"],["Q18173445",275,"personnalite","Leïla Slimani","E","Leïla Slimani, née le 3 octobre 1981 à Rabat au Maroc, est une journaliste et écrivaine franco-marocaine. Elle a notamment reçu le prix Goncourt 2016 pour son deuxième roman, Chanson douce.","Leïla Slimani, née le 3 octobre 1981 à Rabat au Maroc, est une journaliste et écrivaine franco-marocaine.","fr:Leïla_Slimani","c:9/9a/Le%C3%AFla_Slimani_at_the_2025_Cannes_Film_Festival_14.jpg"],["Q3277803",276,"personnalite","Mahmoud Guinia","C","El Mâalem Mahmoud Guinia, de son nom Mahmoud Guinia ou, né en 1951 à Essaouira et mort le 2 août 2015, est un musicien marocain Gnaoui.",118,"fr:Mahmoud_Guinia","c:8/8d/Maalem_Mahmoud_Guinia.jpg"],["Q43388492",278,"personnalite","Manal","C","Manal Benchlikha, dite simplement Manal, née le 18 septembre 1993 à Marrakech, est une chanteuse de RnB et de pop et musicienne marocaine originaire de Kelaat Sraghna.",116,"fr:Manal_(chanteuse)","c:8/81/Manal.png"],["Q462779",279,"personnalite","Medhi Benatia","E","Medhi Benatia, né le 17 avril 1987 à Courcouronnes, est un footballeur international marocain qui a évolué au poste de défenseur central. Il possède également la nationalité française.",118,"fr:Medhi_Benatia","c:a/a2/Medhi_Benatia.jpg"],["Q510292",280,"personnalite","Mehdi Ben Barka","R","Mehdi Ben Barka, né en janvier 1920 à Rabat et disparu le 29 octobre 1965 à Fontenay-le-Vicomte, est un homme politique marocain qui fut l'un des principaux opposants socialistes au roi Hassan II et le chef de file du mouvement tiers-mondiste et panafricaniste.",119,"fr:Mehdi_Ben_Barka","c:c/ce/Mehdi_Ben_Barka_Anefo.jpg"],["Q276850",281,"personnalite","Meryem du Maroc","PC","Lalla Meryem, née le 26 août 1962 à Rome, princesse et membre de la famille royale marocaine, est la fille aînée et le premier enfant du roi Hassan II et de la princesse Lalla Latifa.",118,"fr:Meryem_du_Maroc","c:a/a1/Princess_Lalla_Meryem.jpg"],["Q335436",282,"personnalite","Mohamed Choukri","C","Mohamed Choukri né le 15 juillet 1935 à Aït Chiker, dans la Province de Nador, au Maroc, et mort le 15 novembre 2003 à Rabat, est un écrivain marocain, dont les livres sont principalement écrits en arabe classique.",118,"fr:Mohamed_Choukri","c:5/5a/%D9%85%D9%86%D8%B8%D8%B1_%D9%85%D9%86_%D9%85%D9%82%D9%87%D9%89_%D8%A7%D9%84%D8%AD%D8%A7%D9%81%D8%A9.jpeg"],["Q193874",283,"personnalite","Mohammed V","R","Sidi Mohammed, ou Sidi Mohammed ben Youssef, né le 10 août 1909 à Fès et mort le 26 février 1961 à Rabat, est le sultan du Maroc pendant le protectorat français puis, à la suite de l'indépendance de l'État retrouvée en 1956, le roi du Maroc sous le nom de Mohammed V.",119,"fr:Mohammed_V_(roi_du_Maroc)","c:4/4f/Mohammed_V_Morocco_1957.lowres_%28cropped%29.jpeg"],["Q57553",284,"personnalite","Mohammed VI","M","Mohammed VI, né le 21 août 1963 à Rabat, est le vingt-troisième monarque de la dynastie alaouite, et le troisième à porter le titre de roi du Maroc, depuis le 23 juillet 1999. Il succède cette année-là à son père, Hassan II.",115,"fr:Mohammed_VI","c:7/7c/Pedro_S%C3%A1nchez_se_re%C3%BAne_con_el_rey_de_Marruecos%2C_Mohamed_VI_%281%29_%28cropped%29.jpg",{"cats":["maroc","politique"]}],["Q97057650",285,"personnalite","Morad","PC","Morad, de son nom complet Morad El Horami, né le 5 mars 1999 à L'Hospitalet de Llobregat en Catalogne, est un chanteur et rappeur hispano-marocain. Il fait son entrée dans la scène du rap espagnol en 2017 avec son single M.D.L.R, puis en montant un label du même nom.",118,"fr:Morad","c:e/e7/Morad_December_2023.jpg"],["Q311344",286,"personnalite","Mustapha Hadji","PC","Mustapha Hadji, né le 16 novembre 1971 à Ifrane Atlas Saghir, province de Guelmim, Maroc, est un footballeur marocain.",null,"fr:Mustapha_Hadji","c:5/56/Mustapha_Hadji.jpg"],["Q2388301",287,"personnalite","Nabil Ayouch","C","Nabil Ayouch est un réalisateur franco-marocain, né le 1er avril 1969 à Paris. Ses films sont souvent consacrés à des points sensibles de la société marocaine. Ses œuvres sont à plusieurs reprises présentes dans des compétitions cinématographiques internationales telles que les Oscars, ou le Festival de Cannes. Ceci lui vaut à la fois une notoriété particulière et une certaine méfiance des autorités marocaines.","Nabil Ayouch est un réalisateur franco-marocain, né le 1er avril 1969 à Paris.","fr:Nabil_Ayouch","c:d/db/Nabil_Ayouch_2014.jpg"],["Q6959660",288,"personnalite","Naima Samih","C","Naima Samih, en arabe: نعيمة سميح, née à Casablanca le 1er janvier 1953 et morte le 8 mars 2025 à Rabat, est une chanteuse marocaine, considérée comme l'une des meilleures voix féminines de la musique marocaine moderne.",112,"fr:Naima_Samih","c:5/5b/Naima_Samih.jpg"],["Q2631733",289,"personnalite","Najat Aâtabou","C","Najat Aâtabou est une compositrice et chanteuse amazighe de chaâbi marocain. Elle est parfois surnommée « la Lionne de l'Atlas ».","Najat Aâtabou est une compositrice et chanteuse amazighe de chaâbi marocain.","fr:Najat_Aâtabou","c:4/42/NajatAatabou1.jpg"],["Q268529",290,"personnalite","Najat Vallaud-Belkacem","E","Najat Vallaud-Belkacem, née Belkacem le 4 octobre 1977 à Beni Chiker, est une femme politique française.",null,"fr:Najat_Vallaud-Belkacem","c:9/97/Najat_Vallaud-Belkacem_2018_cropped.jpg",{"cats":["maroc","politique_fr"]}],["Q3090329",291,"personnalite","Nass El Ghiwane","C","Nass El Ghiwane est un groupe musical marocain, né dans les années 1970 à Casablanca au quartier Hay Mohammadi, l'un des quartiers les plus riches en diversité intellectuelle et culturelle de la ville et composé au départ de six musiciens: Laarbi Batma, Allal Yaâla, Moulay Abdelaziz Tahiri, Omar Sayed, Raifak Redouane, Mohamed Akhdim et Boujmîa Hagour.",116,"fr:Nass_El_Ghiwane",""],["Q239993",292,"personnalite","Nawal El Moutawakel","C","Nawal El Moutawakel, née le 15 avril 1962 à Casablanca, est une athlète marocaine, devenue dirigeante sportive et femme politique.",119,"fr:Nawal_El_Moutawakel","c:1/1d/PortraitNawalElMoutawakelJune2016.jpg"],["Q28872567",293,"personnalite","Nayef Aguerd","PC","Nayef Aguerd né le 30 mars 1996 à Kénitra, est un footballeur international marocain qui évolue au poste de défenseur central à l'Olympique de Marseille.",117,"fr:Nayef_Aguerd","c:d/d4/Nayef_Aguerd_vs_Niger%2C_5_Sept_2025.jpg"],["Q374523",294,"personnalite","Nordin Amrabat","PC","Noureddine Amrabat — nom couramment retranscrit en français Nordin Amrabat — né le 31 mars 1987 à Naarden aux Pays-Bas, est un footballeur international marocain évoluant au poste d'ailier au Wydad Athletic Club.",119,"fr:Nordin_Amrabat","c:e/e9/N._Amrabat.jpg"],["Q137899",295,"personnalite","Noureddine Naybet","C","Noureddine Naybet est un ancien footballeur international marocain né le 10 février 1970 à Casablanca.",null,"fr:Noureddine_Naybet","c:1/19/%D9%86%D9%88%D8%B1_%D8%A7%D9%84%D8%AF%D9%8A%D9%86_%D8%A7%D9%84%D9%86%D9%8A%D8%A8%D8%AA_%28cropped%29.jpg"],["Q26266244",296,"personnalite","Noussair Mazraoui","R","Noussair Mazraoui, né le 14 novembre 1997 à Leyde aux Pays-Bas, est un footballeur international marocain jouant au poste d'arrière droit à Manchester United.",115,"fr:Noussair_Mazraoui","c:5/52/Noussair_Mazraoui_France_v_Morocco_9_July_2026-125_%28cropped%29.jpg"],["Q23007827",297,"personnalite","Oussama Idrissi","C","Oussama Idrissi, né le 6 février 1996 à Berg-op-Zoom, est un footballeur international marocain évoluant au poste d'ailier gauche au CF Pachuca. Il possède également la nationalité néerlandaise.",113,"fr:Oussama_Idrissi","c:0/0c/Idrissi_Gazinskiy_2020.jpg"],["Q175176",298,"personnalite","Rachid ben El-Hassan Alaoui","PC","Moulay Rachid, né le 20 juin 1970, est un membre de la famille royale marocaine, fils du roi Hassan II et frère cadet du roi Mohamed VI.",117,"fr:Rachid_ben_El-Hassan_Alaoui","c:9/93/Prince_Moulay_Rachid_at_the_Enthronement_of_Naruhito_%281%29.jpg"],["Q323470",299,"personnalite","RedOne","PC","RedOne, de son vrai nom Nadir Khayat, né le 9 avril 1972 à Tétouan, est un producteur, chanteur, auteur-compositeur-interprète et réalisateur artistique maroco-suédois. Durant sa carrière, il produit de nombreuses chansons notamment pour Lady Gaga comme Just Dance, Poker Face, LoveGame ou encore Bad Romance, ainsi que Fire Burning pour Sean Kingston.",96,"fr:RedOne","c:3/3e/RedOne_2017_press_image.jpg"],["Q3440768",300,"personnalite","Romain Saïss","C","Romain Saïss, parfois appelé par son second prénom Ghanem Saïss, né le 26 mars 1990 à Bourg-de-Péage, en France, est un footballeur international marocain évoluant au poste de défenseur central.",119,"fr:Romain_Saïss","c:1/11/Romain_Sa%C3%AFss_against_Burkina_Faso_%28cropped%29.jpg"],["Q19630169",301,"personnalite","Saad Lamjarred","R","Saad Lamjarred est un auteur-compositeur-interprète, danseur, producteur de musique, multi-instrumentiste et acteur marocain né le 7 avril 1985 à Rabat. Figure majeure de la pop arabe, il est le premier chanteur ayant popularisé la musique pop en dialecte marocain, réputé difficilement compréhensible au Moyen-Orient.",115,"fr:Saad_Lamjarred","c:1/11/Saad_Lamjarred_Star_Academy_2015.jpg"],["Q238691",302,"personnalite","Salma Bennani","R","Lalla Salma, née Salma Abdelhamid Bennani, le 10 mai 1977 à Fès, au Maroc, est un ancien membre de la famille royale marocaine, et la princesse consort du Maroc du 12 juillet 2002 jusqu'à son divorce avec le roi Mohammed VI le 21 mars 2018.",116,"fr:Salma_Bennani","c:7/7c/Princess_Lalla_Salma.jpg"],["Q578416",303,"personnalite","Samira Saïd","PC","Samira Saïd, en arabe: سميرة سعيد, de son vrai nom Samira Bensaïd, née à Rabat le 10 janvier 1958, est une chanteuse et compositrice marocaine. Elle se fait remarquer pour ses prestations d'arabian pop et réussit à percer en Égypte.",119,"fr:Samira_Saïd","c:5/57/Beirut_International_Awards_Festivals_%28BIAF%29_honored_Samira_Said_in_2011.jpg"],["Q311364",304,"personnalite","Saïd Aouita","C","Saïd Aouita, né le 2 novembre 1959 à Kénitra, est un athlète marocain, spécialiste des épreuves de fond et de demi-fond. Il est le seul athlète de l'histoire à avoir gagné deux médailles olympiques sur 800 mètres et 5 000 mètres.","Saïd Aouita, né le 2 novembre 1959 à Kénitra, est un athlète marocain, spécialiste des épreuves de fond et de demi-fond.","fr:Saïd_Aouita","c:e/e3/Said_Aouita.jpg"],["Q18637185",306,"personnalite","Sofiane Boufal","PC","Sofiane Boufal, né le 17 septembre 1993 à Paris, est un footballeur international marocain évoluant au poste d'ailier gauche ou de milieu offensif au Al-Ittihad SC.",117,"fr:Sofiane_Boufal","c:c/cc/Sofiane_Boufal_v_Augsburg_2017.jpg"],["Q18428483",307,"personnalite","Sofyan Amrabat","R","Sofyan Amrabat, né le 21 août 1996 à Huizen aux Pays-Bas, est un footballeur international marocain évoluant au poste de milieu de terrain à l'Ajax Amsterdam.",117,"fr:Sofyan_Amrabat","c:9/9f/Sofyan_Amrabat_Brazil_V_Morocco_13_June_2026-63.jpg"],["Q26393298",308,"personnalite","Soufiane el-Bakkali","C","Soufiane el-Bakkali, né le 7 janvier 1996 à Fès, est un athlète marocain, spécialiste du 3 000 mètres steeple.",null,"fr:Soufiane_el-Bakkali","c:e/ee/Soufiane_el-Bakkali_%28cropped%29_Athletissima_2022.jpg"],["Q334989",309,"personnalite","Tahar Ben Jelloun","PC","Tahar Ben Jelloun est un écrivain, poète et peintre franco-marocain né le 15 décembre 1947 à Fès. Auteur de nouvelles, romans, poèmes et essais, il est lauréat du prix Goncourt pour son roman La Nuit sacrée.","Tahar Ben Jelloun est un écrivain, poète et peintre franco-marocain né le 15 décembre 1947 à Fès.","fr:Tahar_Ben_Jelloun","c:2/22/Tahar_Ben_Jelloun_par_Claude_Truong-Ngoc_sept_2013.jpg"],["Q230497",310,"personnalite","Tariq ibn Ziyad","R","Tariq ibn Ziyad al Ulhassi al Nafzawi al Lawati (en arabe: طارق بن زياد), en berbère: ⵜⴰⵔⵉⵇ ⵓ ⵣⵉⵢⴰⴷ), né au VIIe siècle au Maghreb, et mort vers 720 à Damas, est un stratège militaire et gouverneur omeyyade d'origine berbère. Il est, avec Tarif ibn Malik et Munuza, l'un des principaux acteurs de la conquête musulmane de la péninsule Ibérique.",119,"fr:Tariq_ibn_Ziyad","c:7/70/Tariq-ibn-Ziyad---w.jpg"],["Q3052128",311,"personnalite","Walid Regragui","PC","Hoalid Regragui, appelé communément Walid Regragui, né le 23 septembre 1975 à Corbeil-Essonnes, est un footballeur international marocain, reconverti entraîneur.",114,"fr:Walid_Regragui","c:1/11/RegraguiCoach.jpg"],["Q3571952",312,"personnalite","Yassine Bounou","R","Yassine Bounou surnommé Bono, né le 5 avril 1991 à Montréal au Québec, est un footballeur international marocain évoluant au poste de gardien de but au Al-Hilal FC.",112,"fr:Yassine_Bounou","c:c/c8/Yassine_Bounou_Brazil_V_Morocco_13_June_2026-160.jpg"],["Q348266",313,"personnalite","Younès Belhanda","R","Younès Belhanda, né le 25 février 1990 à Avignon, est un footballeur international marocain. Il est également de nationalité française.","Younès Belhanda, né le 25 février 1990 à Avignon, est un footballeur international marocain.","fr:Younès_Belhanda","c:8/8e/Adana_Demirspor_vs_Antalyaspor_20220225_4_%28cropped%29.jpg"],["Q369981",314,"personnalite","Youssef ben Tachfine","PC","Youssef ben Tachfine as-Sanhaji, aussi nommé Yusuf Ibn Tashfin, est le troisième imam et le premier sultan de la dynastie berbère des Almoravides, ses prédécesseurs étaient émirs.",112,"fr:Youssef_ben_Tachfine","c:7/7d/Yusuf_Ben_Tasfin_dinar_22562.jpg"],["Q26262219",315,"personnalite","Youssef En-Nesyri","R","Youssef En-Nesyri, né le 1er juin 1997 à Fès, est un footballeur international marocain jouant au poste d'attaquant au Ittihad Club.",118,"fr:Youssef_En-Nesyri","c:2/26/Ennesyri.jpg"],["Q52603",316,"ville","Ksar El Kébir","C","Ksar El Kébir est une ville du Maroc située dans la région de Tanger-Tétouan-Al Hoceïma, au nord du pays. C'est la ville la plus peuplée de la province de Larache; lors du recensement de 2018, elle comptait 126 817 habitants: les Kasris.","Ksar El Kébir est une ville du Maroc située dans la région de Tanger-Tétouan-Al Hoceïma, au nord du pays.","fr:Ksar_El_Kébir","c:8/8c/Images325_CP_Maroc%2C_El-Ksar%2C_Alcacer_Quibir._Vue_panoramique.jpg"],["Q2542724",317,"ville","Ben Guerir","C","Ben Guerir ou Benguérir est une ville du Maroc située dans la région de Marrakech-Safi. Elle est le chef-lieu de la province de Rehamna.","Ben Guerir ou Benguérir est une ville du Maroc située dans la région de Marrakech-Safi.","fr:Ben_Guerir","c:d/da/Ben_guerir.png"],["Q842810",318,"ville","Es-Semara","C","Es-Semara, Semara, Esmara ou Smara est une ville du Sahara occidental sous contrôle marocain. Elle comptait 40 347 habitants en 2004. Au dernier recensement de 2014, la population de la ville s'élevait à 57 035 habitants, tandis que l'ensemble de la province compte 66 014 habitants.","Es-Semara, Semara, Esmara ou Smara est une ville du Sahara occidental sous contrôle marocain.","fr:Es-Semara","c:e/e5/Smara%2CrooftopE.jpg"],["Q425646",319,"ville","Figuig","C","Figuig est une ville oasis située à l'extrême est du Maroc, dans la région de l'Oriental, à environ 368 km au sud d'Oujda, sur la frontière algérienne. Elle est formée de plusieurs ksour entourés d'une vaste palmeraie.",113,"fr:Figuig","https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Figuig_land.jpg/3840px-Figuig_land.jpg"],["Q602426",320,"ville","Ouezzane","C","Ouezzane est une ville du nord-ouest du Maroc, proche du Rif occidental, au sud de l'oued Loukkos, comptant environ 60 000 habitants. Ville sainte fondée autour de la zaouïa de Moulay Abdellah Cherif au XVIIe siècle, elle est aussi un lieu de pèlerinage juif et réputée pour son artisanat de la laine.",118,"fr:Ouezzane","c:a/a7/Ciudad_de_uezan.jpg"],["Q990115",321,"ville","Khénifra","C","Khénifra est une ville du Moyen Atlas central au Maroc, chef-lieu de la province du même nom, dans la région de Béni Mellal-Khénifra. Surnommée la « Ville rouge » pour la couleur rougeâtre des façades de ses maisons, elle est bâtie sur les deux rives basaltiques de l'Oum Errabiâ.",116,"fr:Khénifra","c:e/e0/Khenifra_Amazigh.JPG"],["Q1724990",322,"ville","Oued Zem","C","Oued Zem, parfois surnommée la ville martyre, est une ville marocaine de plus de 115 000 habitants, mais l'agglomération de Oued Zem regroupe plus de 200 000 habitants. C'est une communauté urbaine qui se situe dans la région de Béni Mellal-Khénifra, au sein de la province de Khouribga.",104,"fr:Oued_Zem","https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/%D8%B4%D8%A7%D8%B1%D8%B9_%D8%A7%D9%84%D8%AF%D8%A7%D8%B1_%D8%A7%D9%84%D8%A8%D9%8A%D8%B6%D8%A7%D8%A1.jpg/3840px-%D8%B4%D8%A7%D8%B1%D8%B9_%D8%A7%D9%84%D8%AF%D8%A7%D8%B1_%D8%A7%D9%84%D8%A8%D9%8A%D8%B6%D8%A7%D8%A1.jpg"],["Q2501786",323,"ville","Tiflet","C","Tiflet est une ville marocaine qui relève du cercle de même nom, dépendant de la province de Khémisset, au sein de la région Rabat-Salé-Kénitra. Elle est située dans une position de relais à l’échelle régionale. Elle se trouve en bordure de la plaine du Gharb, à 56 km à l’est de la capitale nationale Rabat et de la côte atlantique.",117,"fr:Tiflet","https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Landscape_from_tiflet_near_the_capital_of_Morocco.jpg/1920px-Landscape_from_tiflet_near_the_capital_of_Morocco.jpg"],["Q2548730",324,"ville","Taounate","C","Taounate est une ville du Maroc, chef-lieu de la Province de Taounate, dans la région de Fès-Meknès. Elle est située dans le pays Jbala, au sud du Rif, à environ 80 km au nord de Fès.","Taounate est une ville du Maroc, chef-lieu de la Province de Taounate, dans la région de Fès-Meknès.","fr:Taounate","c:e/e0/AIN_BARDA_-_Biggest_douar_in_the_commune_of_Ghafsai_-_Taounate_-_Morocco.jpg"],["Q144416",325,"ville","Zaïo","C","Zaïo ou en berbère Tayyu est une commune et ville, municipalité de la province de Nador située dans la région administrative de l'Oriental et la région géographique du Rif, plus précisément au Rif oriental, à mi-chemin entre les villes de Nador et Berkane, au Maroc.",109,"fr:Zaïo","c:c/cd/Zaio_maroc_08-2004.jpg"],["Q1635606",326,"ville","Témara","C","Témara est une ville de la préfecture de Skhirate-Témara, dont elle est le chef-lieu, dans la région Rabat-Salé-Kénitra, au Maroc.",100,"fr:Témara","c:e/e7/Temara_porte_de_la_kasbah.jpg"],["Q936316",327,"ville","Tan-Tan","C","Tan-Tan est une ville désertique du sud-ouest du Maroc, chef-lieu de la province de Tan-Tan, dans la région de Guelmim-Oued Noun. Peuplée d'environ 73 000 habitants, elle est connue pour son moussem, grand rassemblement des tribus nomades inscrit au patrimoine culturel immatériel de l'UNESCO.",110,"fr:Tan-Tan","https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Tan_tan.jpg/1920px-Tan_tan.jpg"],["Q3149573",328,"ville","Imsouane","C","Imsouane est une commune territoriale de la préfecture d'Agadir Ida-Outanane, dans la région de Souss-Massa, au Maroc. Elle ne dispose pas de centre urbain mais son chef-lieu est un village du même nom.","Imsouane est une commune territoriale de la préfecture d'Agadir Ida-Outanane, dans la région de Souss-Massa, au Maroc.","fr:Imsouane","c:9/9d/Imsouane-vue_du_village-avoulot.jpg"],["Q3135328",329,"ville","Oualidia","C","Oualidia, ou Loualidia, est une ville du Maroc située dans la province de Sidi Bennour dans la région de Casablanca-Settat, sur la côte atlantique, entre El Jadida et Safi, à 158 km au sud de Casablanca et 212 km de Marrakech. Elle constitue le centre urbain de la commune rurale du même nom.",104,"fr:Oualidia","https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Oualidia_vagues_sur_la_falaise-photo_Bertrand_SOUBEYRAND.jpg/3840px-Oualidia_vagues_sur_la_falaise-photo_Bertrand_SOUBEYRAND.jpg"],["Q2329701",330,"ville","Taourirt","C","Taourirt est une ville du nord-est du Maroc, chef-lieu de la province de Taourirt, dans la région de l'Oriental, à une centaine de kilomètres à l'ouest d'Oujda. Peuplée d'environ 100 000 habitants, elle est un carrefour routier et ferroviaire entre Oujda, Fès et Nador, sur les bords de l'oued Za.",118,"fr:Taourirt_(Maroc)","c:5/56/EKn7E5JW4AIPgLk.jpg"],["Q1014625",331,"ville","M'Hamid El Ghizlane","C","M'Hamid El Ghizlane, anciennement nommée Targala et par erreur médiatique taragalt, est une commune rurale marocaine de la province de Zagora, dans la région de Drâa-Tafilalet, située à la lisière du Sahara, sur les confins algéro-marocains.",119,"fr:M'Hamid_El_Ghizlane","c:2/24/Dunes_of_MHamid_%282357498901%29.jpg"],["Q1009308",332,"ville","Séfrou","C","Séfrou est une ville du centre du Maroc, chef-lieu de la province de Séfrou, dans la région de Fès-Meknès, au pied du Moyen Atlas à une trentaine de kilomètres de Fès. Ancienne cité qui abrita une importante communauté juive, elle est célèbre pour son festival des cerises, organisé chaque année depuis 1920.",117,"fr:Séfrou","https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Sefrou%2C_region_fes.jpg/3840px-Sefrou%2C_region_fes.jpg"],["Q785945",333,"ville","Oulad Teïma","C","Oulad Teima ou Ouled Teima ou encore Houara, est une ville du Maroc, dans la région de Souss-Massa. Elle est située entre Agadir et Taroudant dans la plaine du Souss. Oulad Teïma est traversée par la N 10.","Oulad Teima ou Ouled Teima ou encore Houara, est une ville du Maroc, dans la région de Souss-Massa.","fr:Oulad_Teïma","c:f/fd/Ouled_teima.jpg"],["Q895029",334,"ville","Bejaâd","C","Bejaâd est une ville du Maroc, située dans la région de Béni Mellal-Khénifra. Centre culturel important. Dès sa création, elle se dote en effet d’une multitude de médersas qui fournissent au Maroc quelques-uns de ses plus éminents ouléma. Au départ purement religieux, l’enseignement dispensé dans ces médersas se diversifie au fil des siècles.","Bejaâd est une ville du Maroc, située dans la région de Béni Mellal-Khénifra.","fr:Bejaâd","c:3/38/Boujad%2C_Platz.JPG"],["Q2089594",335,"ville","Sidi Kacem","C","Sidi Kacem est une ville moyenne du nord-ouest du Maroc, chef-lieu de la province du même nom, dans la région de Rabat-Salé-Kénitra. Située dans la plaine agricole du Gharb, elle est un nœud ferroviaire important et a longtemps accueilli une raffinerie de pétrole.",112,"fr:Sidi_Kacem",""],["Q2330467",336,"ville","Guercif","C","Guercif est une ville du Maroc située dans la région de l'Oriental, au nord-est du royaume. Elle est le chef-lieu de la province de Guercif depuis le 1er mars 2010. La ville est bordée au nord par le Rif oriental et au sud par le Moyen Atlas, à la confluence de la Moulouya et de ses affluents.","Guercif est une ville du Maroc située dans la région de l'Oriental, au nord-est du royaume.","fr:Guercif","c:5/57/Photographies_de_Guercif%2C_Maroc.png"],["Q2895854",337,"ville","Fkih Ben Salah","C","Fkih Ben Salah est une ville du Maroc. Située dans la région de Béni Mellal-Khénifra, à 40 km de Béni Mellal, elle est le chef-lieu de la province de Fkih Ben Salah depuis 2009 et faisait auparavant partie de la province de Béni-Mellal.","Fkih Ben Salah est une ville du Maroc.","fr:Fkih_Ben_Salah","c:5/50/Somewhere_in_Fekih.jpg"],["Q1780997",338,"ville","Tata","C","Tata est une ville du sud du Maroc, chef-lieu de la province de Tata, dans la région de Souss-Massa. Oasis de l'Anti-Atlas aux portes du Sahara, elle compte près de 20 000 habitants et est entourée de palmeraies et de ksour.","Tata est une ville du sud du Maroc, chef-lieu de la province de Tata, dans la région de Souss-Massa.","fr:Tata_(Maroc)","c:0/0c/Tata_Morocco_Main_Square.jpg"],["Q2676569",339,"ville","Imilchil","C","Imilchil est une petite commune rurale du Haut Atlas oriental, dans la province de Midelt, peuplée d'environ 2 000 habitants. Elle est célèbre pour son moussem des fiançailles, où les jeunes de la tribu des Aït Haddidou se rencontraient pour se marier, et pour ses lacs d'Isli et de Tislit, liés à une légende d'amour impossible.",114,"fr:Imilchil","c:8/8d/20180922_183434_%D8%A5%D9%85%D9%84%D8%B4%D9%8A%D9%84_%D8%A7%D9%84%D9%85%D8%BA%D8%B1%D8%A8.jpg"],["Q6395311",340,"ville","Ketama","C","Ketama, est une commune rurale marocaine de la province d'Al Hoceïma, dans la région Tanger-Tétouan-Al Hoceima. Elle est aussi considérée comme une tribu de Sanhadja de Srayr.","Ketama, est une commune rurale marocaine de la province d'Al Hoceïma, dans la région Tanger-Tétouan-Al Hoceima.","fr:Ketama_(commune)","c:8/8e/%D8%AB%D9%84%D9%88%D8%AC_%D9%83%D8%AA%D8%A7%D9%85%D8%A9.jpg"],["Q2359952",341,"ville","Sidi Slimane","C","Sidi Slimane est une ville du nord-ouest du Maroc, chef-lieu de la province de Sidi Slimane, dans la région de Rabat-Salé-Kénitra. Peuplée d'environ 95 000 habitants, elle se trouve dans la plaine agricole du Gharb, à une soixantaine de kilomètres de la ville portuaire de Kénitra.",110,"fr:Sidi_Slimane_(Maroc)","c:6/6e/Gare_de_train_de_Sidi_Slimane.jpg"],["Q3299405",342,"ville","Mirleft","C","Mirleft est une commune rurale marocaine de la province de Sidi Ifni, dans la région administrative de Guelmim-Oued Noun. Elle a pour chef-lieu un village amazigh du même nom.",115,"fr:Mirleft","https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Mirleft_Center.jpg/3840px-Mirleft_Center.jpg"],["Q1333077",343,"ville","Skhirat","C","Skhirat est une ville balnéaire du Maroc située entre Rabat, la capitale administrative, et Casablanca, la capitale économique. Elle dépend de la préfecture Skhirat-Témara.",115,"fr:Skhirat","c:7/79/GareSkhirate.JPG"],["Q599897",344,"ville","Boujdour","C","Boujdour est une ville dans le Sahara occidental, à proximité du cap Boujdour. Administrée de facto par le Maroc qui l'inclut dans le découpage administratif des provinces du Sud, elle est dans ce cadre une commune urbaine de la province de Boujdour, dans la région Laâyoune-Sakia El Hamra.","Boujdour est une ville dans le Sahara occidental, à proximité du cap Boujdour.","fr:Boujdour","c:7/71/Ruta_N1_a_la_salida_de_Bojador_%28Sahara_Occidental%29.jpg"],["Q2435851",345,"ville","Boumalne-Dadès","C","Boumalne-Dadès est une petite ville du sud-est du Maroc, dans la province de Tinghir, région de Drâa-Tafilalet, peuplée d'environ 12 000 habitants. Située à l'entrée des gorges du Dadès, au carrefour de la route des Mille Kasbahs, elle est une étape touristique très fréquentée.",119,"fr:Boumalne-Dadès","c:a/ac/Morocco%2C_Dr%C3%A2a-Tafilalet_Region%2C_Tinghir_Province%2C_Boumalne-Dad%C3%A8s_%282%29.jpg"],["Q2627209",346,"ville","Youssoufia","C","Youssoufia ou Louis-Gentil est une ville et commune — municipalité — marocaine, chef-lieu de la province de Youssoufia, dans la région de Marrakech-Safi.",119,"fr:Youssoufia_(Maroc)","c:7/74/Yous_1.jpg"],["Q2191860",347,"ville","Berrechid","C","Berrechid est une ville marocaine située dans la région de Casablanca-Settat. Sa participation dans l'agriculture au niveau national marocain est de 13,25 %. La ville est située à environ 39 km de Ben Ahmed, à 34 km de Settat, à 32 km au sud de Casablanca, à 196 km de Marrakech et à 90 km d'El Jadida.","Berrechid est une ville marocaine située dans la région de Casablanca-Settat.","fr:Berrechid","https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Berrechid_Province_administration_building_in_Berrechid_-_front_2024.jpg/3840px-Berrechid_Province_administration_building_in_Berrechid_-_front_2024.jpg"],["Q1970952",348,"ville","Benslimane","C","Benslimane est une ville du Maroc, chef-lieu de la province de Benslimane, située dans la région de Casablanca-Settat. Auparavant, elle faisait partie de la région Chaouia-Ouardigha.","Benslimane est une ville du Maroc, chef-lieu de la province de Benslimane, située dans la région de Casablanca-Settat.","fr:Benslimane","c:a/a5/Ville_Benslimane_Maroc.JPG"],["Q986666",349,"ville","Skoura","C","Skoura est une importante palmeraie de 25 km2, située à 40 km de Ouarzazate dans le Sud du Maroc. C'est l'une des rares palmeraies du pays encore habitée et cultivée. On y recense environ trente mille habitants et cent trente huit mille palmiers. Skoura est un village marocain appartenant à la confédération tribale Skoura Ait ou Ahl Al Ouast et dont le nom viens du berbère Askur ou Skur qui veut dire perdrix ou bien perdraux.","Skoura est une importante palmeraie de 25 km2, située à 40 km de Ouarzazate dans le Sud du Maroc.","fr:Skoura","c:2/21/Morocco%2C_Souss-Massa-Draa_Region%2C_Ouarzazate_Province%2C_Skoura_%289%29.JPG"],["Q2501764",350,"ville","M'diq","C","M'diq, ou communément appelée Rincón, qui veut dire « coin » ou « recoin » en espagnol, est située dans la préfecture de M'diq-Fnideq. Ses habitants sont les Mdikis. En 2003, sa population était de 60 000 habitants. M'diq est connue pour sa forte attraction touristique durant la période d'été.",117,"fr:M'diq","c:2/27/M%27diq.jpg"],["Q2544620",351,"ville","Ahfir","C","Ahfir est une ville du nord-est du Maroc, dans la province de Berkane, région de l'Oriental. Située sur la rive gauche de l'oued Kiss, elle est accolée à la frontière algérienne, non loin de la station balnéaire de Saïdia.","Ahfir est une ville du nord-est du Maroc, dans la province de Berkane, région de l'Oriental.","fr:Ahfir","c:3/3a/Ahfir%2C_Berkane_Province%2C_Oriental_Region%2C_Morocco.jpg"],["Q4418748",352,"ville","Sidi Bennour","C","Sidi Bennour également appelée Doukkala et Tlat Sidi Bennour, est une ville marocaine de l'ouest du pays appartenant à la province de Sidi Bennour et a 55 815 habitants. Sidi Bennour est située à environ 67 km au sud d'El Jadida, à 120 km au nord-ouest de Marrakech, à environ 100 km à l'est de Safi et à 210 km au sud-ouest de la capitale marocaine Rabat.",118,"fr:Sidi_Bennour","c:8/8a/Flag_of_Sidi_Bennour.png"],["Q2383366",353,"ville","Ksar Sghir","C","Ksar Sghir est un village et une commune rurale du Maroc, se trouvant sur le littoral méditerranéen du pays Jbala, entre Tanger et Ceuta, sur la rive droite et à l’embouchure d’une rivière qui porte le même nom, proche du port de Tanger Med et siège d'une base navale militaire.",114,"fr:Ksar_Sghir","c:c/c3/Morocco_KsarelSeghir.jpg"],["Q3325538",354,"ville","Moulay Bousselham","C","Moulay Bousselham est une station balnéaire au Maroc, située dans la région de Rabat-Salé-Kénitra à mi-chemin entre Rabat et Tanger.",115,"fr:Moulay_Bousselham","c:1/1f/Moulaybousselham.jpg"],["Q2540234",355,"ville","Demnate","C","Demnate est une ville du Maroc. Administrativement, elle fait partie du cercle d'Oultana, de la province d'Azilal, dans la région de Béni Mellal-Khénifra.","Demnate est une ville du Maroc.","fr:Demnate","c:5/59/Demnate.JPG"],["Q1018286",356,"ville","Kelaat-M'Gouna","C","Kelaat M'Gouna, également connue sous son nom Tachelhit: Tighremt n Imgounen, est une ville du Sud du Maroc, située dans la région de Drâa-Tafilalet et la province de Tinghir. Le nom de la ville s'inspire de la région montagneuse d'Ighil M'Goun et de Asif Imgoun. Principalement peuplée par une communauté Chleuh, Kelaa M'Gouna se trouve dans la célèbre \"Vallée des Roses\".",115,"fr:Kelaat-M'Gouna","c:2/2f/El_Kelaa_Mgouna_%28lluket%29.jpg"],["Q988654",357,"ville","Tarfaya","C","Tarfaya est une ville côtière marocaine, chef-lieu de la province de Tarfaya, dans la région de Laâyoune-Sakia El Hamra. Elle se trouve au bord de l'Atlantique, au niveau du cap Juby, à environ 100 km au nord-est de Laâyoune et 100 km au sud-est de l'île de Lanzarote. Elle fut une escale de l'Aéropostale, où Antoine de Saint-Exupéry dirigea l'escale de Cap Juby.","Tarfaya est une ville côtière marocaine, chef-lieu de la province de Tarfaya, dans la région de Laâyoune-Sakia El Hamra.","fr:Tarfaya","c:5/52/Tarfaya_city.jpg"],["Q178172",358,"ville","Azemmour","C","Azemmour est une ville située sur la côte atlantique, à 16 km au nord d'El Jadida et à 72 km au sud ouest de Casablanca, à l'embouchure du fleuve Oum Errabiâ.",108,"fr:Azemmour","https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Azemmour_muraille_medina-photo_Bertrand_SOUBEYRAND.jpg/3840px-Azemmour_muraille_medina-photo_Bertrand_SOUBEYRAND.jpg"],["Q3985724",359,"ville","El Kelaâ des Sraghna","C","El Kelaâ des Sraghna ou bien Kalaat Sraghna est une ville marocaine située au nord de la ville de Marrakech, à 84 km de celle-ci. Sa population était de 93 927 habitants selon le recensement de 2014. Elle est la capitale de la province de Kalaat Sraghna.",119,"fr:El_Kelaâ_des_Sraghna","c:c/c3/Jardin_Central_Kelaat_Sraghna_2011_by_charaf_bellakhdim.jpg"],["Q638967",360,"ville","Bouznika","C","Bouznika est une ville balnéaire marocaine située dans la province de Benslimane, au sein de la région administrative de Casablanca-Settat.",117,"fr:Bouznika","c:0/02/Bouznika_Bay_vue_generale.jpg"],["Q513678",361,"ville","Fnideq","C","Fnideq, Castillejos est une commune du Maroc. Elle est située dans la région de Tanger-Tétouan-Al Hoceïma. Fnideq est aussi appelée Castillejos, de son nom espagnol. C'est la commune urbaine marocaine la plus proche de l'enclave espagnole de Ceuta.","Fnideq, Castillejos est une commune du Maroc.","fr:Fnideq","c:3/3f/Vista_Parcial_De_Fnideq_Castillejos_Desde_Ceuta_%28158152499%29.jpeg"],["Q1001873",362,"ville","Taliouine","C","Taliouine est une ville du Maroc. Elle est située dans la région de Souss-Massa sur la route nationale n ° 10 entre Ouarzazate et Agadir, à 100 km de Taroudant. Elle est limitée au nord par la province d’El Haouz, à l’ouest par Aoulouz à l’est par Taznakht et au sud par la province de Tata.","Taliouine est une ville du Maroc.","fr:Taliouine","c:c/c6/Taliouine.JPG"],["Q1934167",363,"ville","Azilal","C","Azilal est une ville marocaine située dans le Haut-Atlas, au Maroc. Elle est le chef-lieu de la province d'Azilal, l'une des 5 provinces de la région de Béni Mellal-Khénifra.","Azilal est une ville marocaine située dans le Haut-Atlas, au Maroc.","fr:Azilal","c:7/7c/Azilal_city.jpg"],["Q2736030",364,"ville","Inezgane","C","Inezgane est une ville du sud du Maroc, située entre Agadir et Aït Melloul, dans la vallée du Souss. Inezgane est le chef-lieu de la préfecture Inezgane-Aït Melloul, dans la région administrative Souss-Massa.","Inezgane est une ville du sud du Maroc, située entre Agadir et Aït Melloul, dans la vallée du Souss.","fr:Inezgane","https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Inezgane_Market_Parking_from_Above.jpg/3840px-Inezgane_Market_Parking_from_Above.jpg"],["Q2556989",365,"ville","Imouzzer Kandar","C","Imouzzer Kandar ou Imouzzer du Kandar est une ville du Maroc, située dans la région de Fès-Meknès dans le Moyen Atlas. Cette localité est connue pour produire une eau minérale naturelle en faible teneur en Sodium, mise en bouteille à Immouzer, sous la marque \"aïn Soltane\".","Imouzzer Kandar ou Imouzzer du Kandar est une ville du Maroc, située dans la région de Fès-Meknès dans le Moyen Atlas.","fr:Imouzzer_Kandar","c:2/23/Imouzzer_de_kandar.jpg"],["Q2218997",366,"ville","Chichaoua","C","Chichaoua est une ville du Maroc. Elle est le chef-lieu de la province de Chichaoua, dépendant de la région de Marrakech-Safi. Elle est le carrefour, le passage obligé pour aller à Agadir, Imintanoute, Essaouira, Marrakech et Safi.","Chichaoua est une ville du Maroc.","fr:Chichaoua","https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Chichaoua%2C_Morocco_-_panoramio_%289%29.jpg/3840px-Chichaoua%2C_Morocco_-_panoramio_%289%29.jpg"],["Q2606723",367,"ville","El Hajeb","C","El Hajeb est une commune et ville — municipalité — de la province d'El Hajeb, dont elle est le chef-lieu, dans la région Fès-Meknès, au Maroc.",113,"fr:El_Hajeb","c:7/75/El_Hajeb_avenue_Hassan_II_%28Maroc%29.JPG"],["Q2717415",368,"ville","Agdz","C","Agdz est une petite ville du sud du Maroc, dans la province de Zagora, région de Drâa-Tafilalet, peuplée d'environ 10 000 habitants. Nichée au pied du djebel Kissane et au bord de l'oued Drâa, elle marque l'entrée de la vallée du Drâa et de ses palmeraies.",117,"fr:Agdz","c:0/0f/Agdz.Dr%C3%A2a.jpg"],["Q1734833",369,"ville","Kasba Tadla","C","Kasba Tadla est une ville de la région Béni Mellal-Khénifra, au Maroc, elle fut fondée par la dynastie des Banou Ifren au début du XIe siècle.",118,"fr:Kasba_Tadla","c:9/94/Kasba_Tadla.jpg"],["Q3111649",370,"ville","Goulmima","C","Goulmima, ou Igoulmimen en berbère, est une oasis agricole du Maroc, dans la région de Drâa-Tafilalet. Elle est arrosée par l'oued Ghéris, issu du Haut Atlas central. Comme d'autres localités du Tafilalet, elle possède de nombreux ksour en terre, appelés igherman.","Goulmima, ou Igoulmimen en berbère, est une oasis agricole du Maroc, dans la région de Drâa-Tafilalet.","fr:Goulmima","c:1/1f/Overlooking_Goulmima-davidooms.jpg"],["Q2540367",371,"ville","Missour","C","Missour est une ville de l'est du Moyen Atlas, chef-lieu de la province de Boulemane, dans la région de Fès-Meknès. Peuplée d'environ 28 000 habitants, elle se trouve dans la haute vallée de la Moulouya, au cœur d'une région de steppes entre le Moyen Atlas et les hauts plateaux de l'Oriental.","Missour est une ville de l'est du Moyen Atlas, chef-lieu de la province de Boulemane, dans la région de Fès-Meknès.","fr:Missour","c:c/cf/Tidarin_missour_maroc.jpg"],["Q2294847",372,"ville","Bouskoura","C","Bouskoura est une ville de la banlieue sud de Casablanca, dans la province de Nouaceur, peuplée d'environ 200 000 habitants. Connue pour sa grande forêt et sa vaste zone industrielle, elle se trouve non loin de l'aéroport international Mohammed-V.",113,"fr:Bouskoura","https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Gare_ONCF_Bouskoura_casablanca.jpg/3840px-Gare_ONCF_Bouskoura_casablanca.jpg"],["Q2384142",373,"ville","Aït Melloul","C","Aït Melloul est une ville marocaine, située à 15 km au sud d'Agadir, proche de l'embouchure du fleuve Souss, dans la région Souss-Massa. La ville comptait 171847 habitants lors du recensement de 2014.",116,"fr:Aït_Melloul","https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Traffic_light_Ait_Melloul_2020.jpg/3840px-Traffic_light_Ait_Melloul_2020.jpg"],["Q2287316",374,"ville","Jerada","C","Jerada est une ville du nord-est du Maroc, chef-lieu de la province de Jerada, dans la région de l'Oriental, proche de la frontière algérienne. Longtemps principal centre minier de charbon du pays, elle a connu après la fermeture des mines un fort déclin et des mouvements de protestation en 2017-2018.",118,"fr:Jerada","c:e/ed/Jerada1_.jpg"],["Q3110024",375,"ville","Tamegroute","C","Tamegroute est une ville du Maroc, située à une vingtaine de kilomètres de Zagora, sur l'ancienne route de Tombouctou, dans la vallée du Drâa.",118,"fr:Tamegroute","c:5/5c/Zaouia_Naciria%2C_Tamegroute%2C_79-1.jpg"],["Q1334331",376,"ville","Sijilmassa","C","Sijilmassa est une ancienne ville importante du Moyen Âge au Maroc. Fondée en 757, elle joue dès le VIIIe siècle un rôle majeur dans le commerce transsaharien. Il n’en subsiste aujourd’hui que des ruines modestes.","Sijilmassa est une ancienne ville importante du Moyen Âge au Maroc.","fr:Sijilmassa","https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/The_northern_gate_of_sijilmassa_Mansouria.jpg/3840px-The_northern_gate_of_sijilmassa_Mansouria.jpg"],["Q1936239",377,"ville","Tafraout","C","Tafraout ou Tafraoute est une petite ville berbèrophone marocaine situé dans le Petit-Atlas, chaîne de montagnes au sud-ouest du Maroc située entre le Haut Atlas central et du Souss au Tafilalet. Située à 170/180 km au sud-est d'Agadir dans la région du Souss au cœur de la vallée des Ammeln, à une centaine de kilomètres au sud de Taroudant et à l’est de Tiznit, la ville dépend administrativement de la province de Tiznit, dans la région de Souss-Massa.",115,"fr:Tafraout_(Maroc)","c:b/bd/Village-tafraout.jpg"],["Q2293231",378,"ville","Bouarfa","C","Bouarfa ou Bouârfa est une commune et ville — municipalité — du Maroc, chef-lieu de la province de Figuig, dans la région administrative de l'Oriental.",114,"fr:Bouarfa_(Maroc)","https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Bouarfa_%D8%A8%D9%88%D8%B9%D8%B1%D9%81%D8%A9.JPG/3840px-Bouarfa_%D8%A8%D9%88%D8%B9%D8%B1%D9%81%D8%A9.JPG"],["Q598684",379,"ville","Mehdia","C","Mehdia est une ville du Maroc. Elle est située dans la région de Rabat-Salé-Kénitra. C'est une pittoresque petite ville côtière située près de la ville de Kénitra à 30 km au nord-est de la capitale Rabat.","Mehdia est une ville du Maroc.","fr:Mehdia","c:3/34/Puerta_de_la_alcazaba_de_Mehdia.jpg"],["Q685870",380,"ville","Assa","C","Assa est une petite ville du Sud du Maroc, à 100 km au sud-est de Guelmim, et à 350 km au sud-ouest de Foum Zguid. Elle fait partie de la province d'Assa-Zag dans la région de Guelmim-Oued Noun.","Assa est une petite ville du Sud du Maroc, à 100 km au sud-est de Guelmim, et à 350 km au sud-ouest de Foum Zguid.","fr:Assa_(ville)","https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Assa_City_Skyview.jpg/3840px-Assa_City_Skyview.jpg"],["Q1950230",381,"ville","Moulay Yaâcoub","C","Moulay Yaâcoub est une petite ville située dans les collines au nord-ouest de Fès, dans la région de Fès-Meknès. Elle est connue pour ses sources d'eau thermale sulfureuse et chaude, exploitées depuis des siècles par une station thermale très fréquentée.","Moulay Yaâcoub est une petite ville située dans les collines au nord-ouest de Fès, dans la région de Fès-Meknès.","fr:Moulay_Yaâcoub","c:1/16/Moulai_Yaqoub_viyaedje_tiene.jpg"],["Q3514880",382,"ville","Tamraght","C","Tamraght est un village berbère marocain situé à 15 km au nord d'Agadir, entre Aourir et Taghazout, au bord de l'Atlantique, connu pour avoir les meilleurs spots de surf de la région d'Agadir.",110,"fr:Tamraght","c:e/ed/Tamraght-daleharvey-03-beach.jpg"]]]);